import { Suspense, lazy, useEffect } from 'react'; // Suspense, lazy ve useEffect eklendi
import { BrowserRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import ProtectedRoute from '@/components/ProtectedRoute';
import { AuthProvider, useAuth } from '@/contexts/SupabaseAuthContext';
import { Toaster } from '@/components/ui/toaster';
import AdminLayout from '@/layouts/AdminLayout';
import { AnimatePresence, motion } from 'framer-motion';

// Lazy loading for pages
const LandingPage = lazy(() => import('@/pages/LandingPage'));
const CustomerPanel = lazy(() => import('@/pages/CustomerPanel'));
const AdminPanel = lazy(() => import('@/pages/AdminPanel'));
const FeedbackManagement = lazy(() => import('@/pages/FeedbackManagement'));
const DetailedAnalytics = lazy(() => import('@/pages/DetailedAnalytics'));
const SettingsPage = lazy(() => import('@/pages/SettingsPage'));
const FeedbackForm = lazy(() => import('@/pages/FeedbackForm'));
const QRRedirector = lazy(() => import('@/pages/QRRedirector'));
const NotificationHistory = lazy(() => import('@/pages/NotificationHistory'));
const CustomerDetail = lazy(() => import('@/pages/CustomerDetail'));
const UpdatePassword = lazy(() => import('@/pages/UpdatePassword'));
const ErrorTestPage = lazy(() => import('@/pages/ErrorTestPage'));

// Loading component
// Loading component
// Loading component (Animasyonlu)
const PageLoader = () => (
  <motion.div
    initial={{ opacity: 1 }}
    exit={{ opacity: 0 }}
    transition={{ duration: 0.5, ease: "easeInOut" }}
    className="fixed inset-0 z-[9999] flex flex-col items-center justify-center bg-[#0f172a] text-white"
  >
    <div className="relative flex flex-col items-center">
      {/* Logo Container with Glow */}
      <div className="relative w-32 h-32 md:w-40 md:h-40 mb-8 flex items-center justify-center animate-pulse">
        {/* Background Glows */}
        <div className="absolute inset-0 bg-teal-500/20 rounded-full blur-3xl" />
        <div className="absolute inset-0 bg-orange-500/10 rounded-full blur-2xl delays-75" />
        <img
          src="/faviconmain.png"
          alt="Vocalize Logo"
          className="w-full h-full object-contain relative z-10 drop-shadow-2xl"
        />
      </div>
      {/* Loading Bar */}
      <div className="h-1 w-48 bg-slate-800 rounded-full overflow-hidden relative">
        <div
          className="absolute inset-y-0 left-0 bg-gradient-to-r from-teal-500 to-orange-500 w-1/2"
          style={{ animation: 'shimmer 1.5s infinite linear' }}
        />
      </div>
      <p className="mt-4 text-slate-400 text-sm font-medium tracking-widest uppercase animate-pulse">
        Y├╝kleniyor...
      </p>
      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(200%); }
        }
      `}</style>
    </div>
  </motion.div>
);

// ­şæç YEN─░ B─░LE┼ŞEN: Tema Kontrolc├╝s├╝
// Bu bile┼şen sayfa her de─şi┼şti─şinde ├ğal─▒┼ş─▒r ve temay─▒ ayarlar.
const ThemeController = () => {
  const location = useLocation();

  useEffect(() => {
    // E─şer bulundu─şumuz sayfa '/admin-panel' ile ba┼şl─▒yorsa (Y├Ânetici Paneli i├ğindeysek)
    if (location.pathname.startsWith('/admin-panel')) {
      // Kullan─▒c─▒n─▒n kaydetti─şi tercihi hat─▒rla ve uygula
      const savedTheme = localStorage.getItem('acta_theme');
      if (savedTheme === 'light') {
        document.body.classList.add('light-theme');
      } else {
        document.body.classList.remove('light-theme');
      }
    }
    // E─şer Y├Ânetici Paneli DI┼ŞINDAYSAK (Landing, Feedback Form, Login vb.)
    else {
      // Ayd─▒nl─▒k temay─▒ ZORLA KAPAT (Orijinal koyu temaya d├Ân)
      document.body.classList.remove('light-theme');
    }
  }, [location]); // Her URL de─şi┼şiminde tetiklenir

  return null; // G├Âr├╝nt├╝lenecek bir ┼şeyi yok, sadece mant─▒k ├ğal─▒┼şt─▒r─▒r.
};

// ­şæç Yeni Bile┼şen: Auth Loading Wrapper
// AuthContext'teki loading durumuna g├Âre PageLoader'─▒ g├Âsterir
const AuthLoadingWrapper = ({ children }) => {
  const { loading } = useAuth();

  return (
    <>
      <AnimatePresence>
        {loading && <PageLoader />}
      </AnimatePresence>
      {children}
    </>
  );
};

function App() {
  return (
    <AuthProvider>
      <Router>
        {/* ­şæç ThemeController Router'─▒n i├ğine eklendi */}
        <ThemeController />

        <AuthLoadingWrapper>
          <Suspense fallback={<PageLoader />}>
            <Routes>
              <Route path="/" element={<LandingPage />} />

              <Route path="/scan" element={<QRRedirector />} />

              <Route path="/feedback" element={<FeedbackForm />} />

              <Route path="/update-password" element={<UpdatePassword />} />

              <Route path="/error-test" element={<ErrorTestPage />} />

              <Route element={<ProtectedRoute allowedRole="customer" />}>
                <Route path="/customer-panel" element={<CustomerPanel />} />
              </Route>

              <Route element={<ProtectedRoute allowedRole="manager" />}>
                <Route path="/admin-panel" element={<AdminLayout />}>
                  <Route index element={<AdminPanel />} />
                  <Route path="feedbacks" element={<FeedbackManagement />} />
                  <Route path="analytics" element={<DetailedAnalytics />} />
                  <Route path="settings" element={<SettingsPage />} />
                  <Route path="notifications" element={<NotificationHistory />} />
                  <Route path="customers/:id" element={<CustomerDetail />} />
                </Route>
              </Route>
            </Routes>
          </Suspense>
        </AuthLoadingWrapper>
        <Toaster />
      </Router>
    </AuthProvider>
  );
}

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { useAdminContext } from '@/contexts/AdminContext';
import { useAuth } from '@/contexts/SupabaseAuthContext';
import { Bell, Building2, User, LogOut, QrCode, MessageSquare, X, CheckCheck, AlertOctagon, Sun, Moon, Search } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useNavigate } from 'react-router-dom';
import { supabase } from '@/lib/customSupabaseClient';
import { useToast } from "@/components/ui/use-toast";
import { AnimatePresence, motion } from 'framer-motion';
import FeedbackDetailModal from '@/components/FeedbackDetailModal';
import { cn } from '@/lib/utils';

const formatTimeAgo = (dateString) => {
  if (!dateString) return '';
  const date = new Date(dateString);
  const now = new Date();
  const seconds = Math.floor((now - date) / 1000);
  let interval = seconds / 31536000;
  if (interval > 1) return `${Math.floor(interval)} y─▒l ├Ânce`;
  interval = seconds / 2592000;
  if (interval > 1) return `${Math.floor(interval)} ay ├Ânce`;
  interval = seconds / 86400;
  if (interval > 1) return `${Math.floor(interval)} g├╝n ├Ânce`;
  interval = seconds / 3600;
  if (interval > 1) return `${Math.floor(interval)} sa ├Ânce`;
  interval = seconds / 60;
  if (interval > 1) return `${Math.floor(interval)} dk ├Ânce`;
  return `${Math.floor(seconds)} sn ├Ânce`;
};

const AdminHeader = () => {
  const {
    businessId, businessName, branches, selectedBranchId, setSelectedBranchId,
    qrCount, loading, dateRange,
    isSpecialOffer, monthlyFeeOverride,
    userRole, assignedBranchId, isBranchManager,
    // ­şşó Context-based Notification Data
    notifications, unreadCount, escalatedCount,
    markNotificationAsRead, markAllNotificationsAsRead, checkEscalatedStatus
  } = useAdminContext();

  const { user, signOut } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();
  const notificationRef = useRef(null);

  // --- STATE Y├ûNET─░M─░ ---
  const [notificationOpen, setNotificationOpen] = useState(false);
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);

  // ­şşó REMOVED: Local Notification State (notifications, unreadCount, escalatedCount) moved to Context
  const [selectedFeedback, setSelectedFeedback] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [branchSearchQuery, setBranchSearchQuery] = useState('');

  // --- ┼ŞUBE F─░LTRELEME (Enterprise i├ğin 300+ ┼şube deste─şi) ---
  const filteredBranches = useMemo(() => {
    if (!branchSearchQuery.trim()) return branches;
    const query = branchSearchQuery.toLowerCase().trim();
    return branches.filter(b => b.branch_name_tr.toLowerCase().includes(query));
  }, [branches, branchSearchQuery]);

  // --- TEMA Y├ûNET─░M─░ ---
  const [theme, setTheme] = useState(localStorage.getItem('acta_theme') || 'dark');

  useEffect(() => {
    const root = window.document.body;
    root.classList.remove('light-theme', 'dark-theme');

    if (theme === 'light') {
      root.classList.add('light-theme');
    } else {
      root.classList.add('dark-theme');
    }
    localStorage.setItem('acta_theme', theme);
  }, [theme]);

  const toggleTheme = (e) => {
    if (e && e.preventDefault) {
      e.preventDefault();
      e.stopPropagation();
    }
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  // --- MEN├£ KONTROL├£ (├çAKI┼ŞMAYI ├ûNLEME) ---
  const toggleNotifications = () => {
    if (!notificationOpen) {
      // Bildirim a├ğ─▒l─▒yorsa profili kapat
      setIsProfileMenuOpen(false);
    }
    setNotificationOpen(prev => !prev);
  };

  const handleProfileMenuChange = (isOpen) => {
    setIsProfileMenuOpen(isOpen);
    if (isOpen) {
      // Profil a├ğ─▒l─▒yorsa bildirimi kapat
      setNotificationOpen(false);
    }
  };

  const getNotificationLabel = (n) => {
    const type = n.feedbacks?.feedback_type || n.feedback_type;
    if (type === 'complaint') return 'Yeni bir ┼şikayetiniz var';
    if (type === 'suggestion') return 'Yeni bir ├Âneriniz var';
    if (type === 'evaluation' || type === 'review' || type === 'rating') return 'Yeni bir de─şerlendirmeniz var';
    return n.message || 'Yeni bildirim';
  };

  // ­şşó REMOVED: All local data fetching and subscription logic (fetchNotifications, useEffects)
  // Logic is now in AdminContext to prevent double-subscription and performance issues.

  const handleNotificationClick = async (notification) => {
    const targetId = notification.related_id || notification.feedback_id;
    if (!targetId) return;
    setNotificationOpen(false);

    if (!notification.is_read) {
      // ­şşó Use Context Method
      markNotificationAsRead(notification.id);
    }
    navigate('/admin-panel/feedbacks', { state: { openFeedbackId: targetId } });
  };

  const handleMarkAllAsRead = async () => {
    // ­şşó Use Context Method
    await markAllNotificationsAsRead();
  };

  const handleLogout = async () => { await signOut(); navigate('/'); };

  const getSelectedBranchLabel = () => {
    if (selectedBranchId === 'all') return 'T├╝m ┼Şubeler';
    const branch = branches.find(b => b.id === selectedBranchId);
    return branch ? branch.branch_name_tr : 'T├╝m ┼Şubeler';
  };

  const getQrDateLabel = () => {
    const labels = { 'today': 'Bug├╝n', 'last7': 'Son 7 G├╝n', 'last30': 'Son 30 G├╝n', 'last90': 'Son 90 G├╝n', 'thisMonth': 'Bu Ay', 'allTime': 'T├╝m Zamanlar' };
    return labels[dateRange] || 'Son 7 G├╝n';
  };

  // Badge Config Logic (K─▒salt─▒ld─▒, aynen duruyor)
  let badgeConfig = null;
  if (!loading && isSpecialOffer === true && monthlyFeeOverride !== null) {
    const fee = Number(monthlyFeeOverride);
    if (fee === 79.00) {
      badgeConfig = { text: "Erken Eri┼şim", icon: "Ô¡É", badgeClassName: "bg-amber-500/10 border-amber-500/30 text-amber-400 hover:bg-amber-500/20", cardTitle: "Ô¡É Ayr─▒cal─▒kl─▒ Erken Eri┼şim", cardDesc: "Bu i┼şletme Vocalize'─▒n ilk destek├ğileri aras─▒ndad─▒r. Ayl─▒k abonelik bedeli $79 + KDV olarak belirlenmi┼ştir ve ├Âm├╝r boyu %20 indirim hakk─▒ m├╝h├╝rlenmi┼ştir.", cardBorderColor: "border-amber-500/50", cardTitleColor: "text-amber-400" };
    } else {
      badgeConfig = { text: "Esnek Plan", icon: "­şÜÇ", badgeClassName: "bg-teal-500/10 border-teal-500/30 text-teal-400 hover:bg-teal-500/20", cardTitle: "­şÜÇ Kurumsal Esnek Paket", cardDesc: `─░┼şletmenizin ihtiya├ğlar─▒na ├Âzel olarak yap─▒land─▒r─▒lm─▒┼ş ├Âdeme plan─▒d─▒r. Ayl─▒k kullan─▒m bedeli $${fee} + KDV olarak tan─▒mlanm─▒┼şt─▒r.`, cardBorderColor: "border-teal-500/50", cardTitleColor: "text-teal-400" };
    }
  }

  return (
    <>
      <header className="hidden md:flex sticky top-0 z-40 h-16 bg-[#111827] border-b border-slate-800 px-4 md:px-6 items-center justify-between shadow-sm">
        <div className="flex items-center gap-6">
          <span className="text-white font-bold text-xl md:text-2xl truncate max-w-[200px] md:max-w-xs tracking-tight">
            {loading ? "..." : businessName}
          </span>

          {badgeConfig && (
            <div className={cn("relative flex items-center gap-1.5 px-3 py-1.5 rounded-full border transition-all duration-200 cursor-pointer", badgeConfig.badgeClassName)} onMouseEnter={() => setIsHovered(true)} onMouseLeave={() => setIsHovered(false)}>
              <span className="text-sm">{badgeConfig.icon}</span>
              <span className="text-xs font-semibold whitespace-nowrap hidden md:inline-block">{badgeConfig.text}</span>
              <div className={cn("absolute top-full mt-2 left-1/2 -translate-x-1/2 w-64 px-4 py-3 rounded-lg shadow-lg z-50 transition-all duration-200 bg-slate-800 border", badgeConfig.cardBorderColor, isHovered ? "opacity-100 scale-100" : "opacity-0 scale-95 pointer-events-none")}>
                <div className={cn("text-sm font-semibold mb-1", badgeConfig.cardTitleColor)}>{badgeConfig.cardTitle}</div>
                <div className="text-xs text-slate-300">{badgeConfig.cardDesc}</div>
              </div>
            </div>
          )}

          {!loading && branches.length > 1 && (
            <div className="w-56">
              <Select value={selectedBranchId} onValueChange={setSelectedBranchId}>
                <SelectTrigger className="bg-slate-800 border-slate-700 text-slate-200 font-semibold text-base h-10 hover:bg-slate-700 transition-colors">
                  <div className="flex items-center gap-2 truncate">
                    <Building2 className="h-4 w-4 text-slate-400 shrink-0" />
                    <SelectValue placeholder="┼Şube Se├ğiniz">{getSelectedBranchLabel()}</SelectValue>
                  </div>
                </SelectTrigger>
                <SelectContent className="bg-slate-800 border-slate-700 text-white max-h-[300px]">
                  {/* ­şöı ┼ŞUBE ARAMA KUTUSU */}
                  {branches.length > 5 && (
                    <div className="p-2 border-b border-slate-700 sticky top-0 bg-slate-800 z-10">
                      <div className="relative">
                        <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                        <input
                          type="text"
                          placeholder="┼Şube ara..."
                          value={branchSearchQuery}
                          onChange={(e) => setBranchSearchQuery(e.target.value)}
                          onClick={(e) => e.stopPropagation()}
                          onKeyDown={(e) => e.stopPropagation()}
                          className="w-full pl-8 pr-3 py-2 bg-slate-900 border border-slate-700 rounded-md text-sm text-white placeholder:text-slate-500 focus:outline-none focus:border-teal-500/50 focus:ring-1 focus:ring-teal-500/20"
                        />
                      </div>
                    </div>
                  )}
                  <SelectItem value="all">T├╝m ┼Şubeler</SelectItem>
                  {filteredBranches.length === 0 && branchSearchQuery && (
                    <div className="p-3 text-center text-slate-500 text-sm">┼Şube bulunamad─▒</div>
                  )}
                  {filteredBranches.map((branch) => <SelectItem key={branch.id} value={branch.id}>{branch.branch_name_tr}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          )}
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-3 bg-slate-800/50 border border-teal-500/30 rounded-lg px-4 py-2 hover:bg-slate-700/50 transition-colors">
            <QrCode className="h-5 w-5 text-teal-400" />
            <span className="text-sm font-semibold text-teal-300 whitespace-nowrap">
              {getQrDateLabel()}: <span className="text-white font-bold">{loading ? '...' : qrCount}</span> Tarama
            </span>
          </div>

          {/* B─░LD─░R─░M BUTONU (G├£NCELLEND─░: toggleNotifications kullan─▒yor) */}
          <div ref={notificationRef} className="relative">
            <Button onClick={toggleNotifications} variant="ghost" size="icon" className="relative text-slate-400 hover:text-white hover:bg-slate-800">
              <Bell className="h-5 w-5" />
              {(unreadCount > 0 || escalatedCount > 0) && <span className="absolute top-1.5 right-1.5 h-2.5 w-2.5 bg-red-500 rounded-full animate-pulse border-2 border-[#111827]"></span>}
            </Button>
            <AnimatePresence>
              {notificationOpen && (
                <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.2 }}
                  className="absolute top-full right-0 mt-2 w-80 bg-slate-800 border border-slate-700/50 rounded-lg shadow-2xl z-50">
                  <div className="flex items-center justify-between px-4 py-3 bg-slate-700/50 border-b border-slate-700/50">
                    <h3 className="text-white font-bold text-sm">Bildirimler</h3>
                    <div className="flex items-center gap-2">
                      {unreadCount > 0 && <button onClick={handleMarkAllAsRead} className="p-1 text-slate-400 hover:text-white"><CheckCheck className="w-4 h-4" /></button>}
                      <button onClick={() => setNotificationOpen(false)} className="p-1 text-slate-400 hover:text-white"><X className="w-4 h-4" /></button>
                    </div>
                  </div>
                  <div className="max-h-96 overflow-y-auto">
                    {escalatedCount > 0 && (
                      <div onClick={() => { navigate('/admin-panel/feedbacks', { state: { filter: 'urgent' } }); setNotificationOpen(false); }} className="flex items-start gap-3 p-3 border-b border-slate-700/30 bg-red-950/30 hover:bg-red-900/40 cursor-pointer">
                        <AlertOctagon className="w-4 h-4 shrink-0 mt-1 text-red-500 animate-pulse" />
                        <div className="flex-grow">
                          <p className="text-sm text-red-200 font-bold">Acil Durum</p>
                          <p className="text-xs text-red-300 mt-1">{escalatedCount} acil bildirim.</p>
                        </div>
                      </div>
                    )}
                    {notifications.length > 0 ? (
                      notifications.slice(0, 5).map(n => (
                        <div key={n.id} onClick={() => handleNotificationClick(n)} className="flex items-start gap-3 p-3 border-b border-slate-700/30 hover:bg-slate-700/50 cursor-pointer transition-colors last:border-b-0">
                          {!n.is_read && <div className="w-2 h-2 mt-1.5 rounded-full bg-blue-400 shrink-0"></div>}
                          <MessageSquare className={`w-4 h-4 shrink-0 mt-1 ${n.is_read ? 'text-slate-500' : 'text-teal-400'}`} />
                          <div className="flex-grow">
                            <p className={`text-sm ${n.is_read ? 'text-slate-400' : 'text-slate-200 font-medium'}`}>
                              <span className="font-semibold">{n.branch_name}</span>: {getNotificationLabel(n)}
                            </p>
                            <p className="text-xs text-slate-500 mt-1">{formatTimeAgo(n.created_at)}</p>
                          </div>
                        </div>
                      ))
                    ) : escalatedCount === 0 ? (<p className="text-slate-400 text-sm text-center py-8">Bildirim yok.</p>) : null}
                  </div>
                  <div className="px-4 py-3 bg-slate-700/50 border-t border-slate-700/50 text-center">
                    <button onClick={() => { navigate('/admin-panel/notifications'); setNotificationOpen(false); }} className="text-teal-400 hover:text-teal-300 text-sm font-medium w-full">T├╝m├╝n├╝ G├Âr</button>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>

          {/* PROF─░L MEN├£S├£ (G├£NCELLEND─░: Controlled State + Tema Butonu) */}
          <DropdownMenu open={isProfileMenuOpen} onOpenChange={handleProfileMenuChange}>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="icon" className="text-slate-400 hover:text-white hover:bg-slate-800 rounded-full"><User className="h-5 w-5" /></Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-56 bg-slate-800 border-slate-700 text-white">
              <DropdownMenuLabel>Hesab─▒m</DropdownMenuLabel>
              <DropdownMenuSeparator className="bg-slate-700" />
              <DropdownMenuItem onClick={() => navigate('/admin-panel/settings')} className="cursor-pointer focus:bg-slate-700 focus:text-white">Ayarlar</DropdownMenuItem>

              {/* TEMA DE─Ş─░┼ŞT─░R (Kapanmay─▒ ├Ânler) */}
              <DropdownMenuItem
                onSelect={(e) => { e.preventDefault(); toggleTheme(e); }}
                className="cursor-pointer focus:bg-slate-700 focus:text-white flex justify-between items-center group"
              >
                <span>G├Âr├╝n├╝m</span>
                {theme === 'dark' ? (
                  <div className="flex items-center gap-2 text-slate-400 group-hover:text-white">
                    <span className="text-xs">Koyu</span>
                    <Moon className="h-4 w-4" />
                  </div>
                ) : (
                  <div className="flex items-center gap-2 text-yellow-400 group-hover:text-yellow-300">
                    <span className="text-xs">A├ğ─▒k</span>
                    <Sun className="h-4 w-4" />
                  </div>
                )}
              </DropdownMenuItem>

              <DropdownMenuItem onClick={handleLogout} className="logout-menuitem text-red-400 focus:bg-red-900/20 focus:text-red-300 cursor-pointer">
                <LogOut className="mr-2 h-4 w-4" />├ç─▒k─▒┼ş Yap
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </header>
      {isModalOpen && selectedFeedback && <FeedbackDetailModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} feedback={selectedFeedback} />}
    </>
  );
};

export default AdminHeader;

import React, { useEffect, useState, useRef, useMemo } from 'react';
import { useAdminContext } from '@/contexts/AdminContext';
import { Bell, QrCode, Building2, CheckCheck, X, AlertOctagon, Search } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
} from "@/components/ui/select";
import { useNavigate } from 'react-router-dom';
import { supabase } from '@/lib/customSupabaseClient';
import { useAuth } from '@/contexts/SupabaseAuthContext';
import { useToast } from "@/components/ui/use-toast";
import { AnimatePresence, motion } from 'framer-motion';

const formatTimeAgo = (dateString) => {
  if (!dateString) return '';
  const date = new Date(dateString);
  const now = new Date();
  const seconds = Math.floor((now - date) / 1000);
  let interval = seconds / 31536000;
  if (interval > 1) return `${Math.floor(interval)}y`;
  interval = seconds / 2592000;
  if (interval > 1) return `${Math.floor(interval)}ay`;
  interval = seconds / 86400;
  if (interval > 1) return `${Math.floor(interval)}g`;
  interval = seconds / 3600;
  if (interval > 1) return `${Math.floor(interval)}sa`;
  interval = seconds / 60;
  if (interval > 1) return `${Math.floor(interval)}dk`;
  return `${Math.floor(seconds)}sn`;
};

const AdminMobileNavbar = () => {
  const {
    branches,
    selectedBranchId,
    setSelectedBranchId,
    qrCount,
    loading,
