    notifications, unreadCount, escalatedCount,
    markNotificationAsRead, markAllNotificationsAsRead
  } = useAdminContext();


  const { user } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();
  // ­şşó REMOVED: Local Notification Logic (notifications, unreadCount, escalatedCount) is now in Context
  const [showNotifications, setShowNotifications] = useState(false);
  const [branchSearchQuery, setBranchSearchQuery] = useState('');

  const containerRef = useRef(null);

  const filteredBranches = useMemo(() => {
    if (!branchSearchQuery.trim()) return branches;
    const query = branchSearchQuery.toLowerCase().trim();
    return branches.filter(b => b.branch_name_tr.toLowerCase().includes(query));
  }, [branches, branchSearchQuery]);

  // ­şşó REMOVED: All local useEffects for fetching and subscriptions. Context handles it ONE time.

  // ­şşó GER─░ TU┼ŞU Y├ûNET─░M─░: Dropdown a├ğ─▒kken geri tu┼şuna bas─▒l─▒rsa kapat
  useEffect(() => {
    if (!showNotifications) return;

    const handlePopState = () => {
      setShowNotifications(false);
    };

    // Dropdown a├ğ─▒ld─▒─ş─▒nda history'e state ekle
    window.history.pushState({ notificationDropdown: true }, '');

    // Popstate listener (geri tu┼şu)
    window.addEventListener('popstate', handlePopState);

    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, [showNotifications]);

  // Click Outside Handler
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (containerRef.current && !containerRef.current.contains(event.target)) {
        setShowNotifications(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("touchstart", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("touchstart", handleClickOutside);
    };
  }, []);

  const handleBellClick = (e) => {
    e.stopPropagation();
