      });
      return;
    }

    // Ô£à MOB─░L F─░X: localStorage'a ├ûNCE yaz (State kayb─▒na kar┼ş─▒)
    localStorage.setItem('vocalize_pending_feedback', feedbackId);

    // Ô£à DEBUG LOG (Mobil test i├ğin)
    console.log('­şöö Bildirim t─▒kland─▒:', {
      notification_id: notification.id,
      feedback_id: feedbackId,
      localStorage_set: true,
      navigasyon_path: '/admin-panel/feedbacks',
      state_g├Ânderiliyor: { openFeedbackId: feedbackId }
    });

    // Navigate
    navigate('/admin-panel/feedbacks', {
      state: { openFeedbackId: feedbackId }
    });

    // Okundu i┼şaretleme (Context Method)
    if (!notification.is_read) {
      markNotificationAsRead(notification.id);
    }
  };

  const handleMarkAllRead = async (e) => {
    e.stopPropagation();
    await markAllNotificationsAsRead();
  };

  const getSelectedBranchLabel = () => {
    if (selectedBranchId === 'all') return 'T├╝m ┼Şubeler';
    const branch = branches.find(b => b.id === selectedBranchId);
    return branch ? branch.branch_name_tr : 'T├╝m ┼Şubeler';
  };

  if (loading) return null;

  return (
