            <DialogDescription className="text-slate-400">
              G├Âr├╝┼şlerinizi, ├Ânerilerinizi veya ya┼şad─▒─ş─▒n─▒z sorunlar─▒ bizimle payla┼ş─▒n.
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleFeedbackSubmit} className="grid gap-4 py-4">
            <div className="grid gap-2">
              <label htmlFor="feedback-message" className="text-sm font-medium text-slate-200">Mesaj─▒n─▒z *</label>
              <textarea
                id="feedback-message"
                rows="4"
                placeholder="Mesaj─▒n─▒z─▒ buraya yaz─▒n..."
                value={feedbackMessage}
                onChange={(e) => setFeedbackMessage(e.target.value)}
                className="w-full rounded-md border border-slate-700 bg-slate-800 px-3 py-2 text-sm text-white placeholder:text-slate-400 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 resize-none"
                required
              />
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <label className="text-sm font-medium text-slate-200 flex items-center gap-2">
                  <ImageIcon className="w-4 h-4" />
                  G├Ârseller (Opsiyonel)
                </label>
                <span className="text-xs text-slate-500">{feedbackImages.length}/3</span>
              </div>
              
              <div className="flex flex-wrap gap-3">
                {feedbackImages.map((file, idx) => (
                  <div key={idx} className="relative w-20 h-20 rounded-lg overflow-hidden border border-slate-700 group">
                    <img 
                      src={URL.createObjectURL(file)} 
                      alt="preview" 
                      className="w-full h-full object-cover"
                    />
                    <button
                      type="button"
                      onClick={() => removeImage(idx)}
                      className="absolute top-1 right-1 bg-black/60 hover:bg-red-600 text-white rounded-full p-1 transition-colors"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  </div>
                ))}
                
                {feedbackImages.length < 3 && (
                  <label className="w-20 h-20 flex flex-col items-center justify-center border border-dashed border-slate-700 rounded-lg cursor-pointer hover:bg-slate-800/50 hover:border-blue-500/50 transition-colors">
                    <Upload className="w-5 h-5 text-slate-400 mb-1" />
                    <span className="text-[10px] text-slate-500">Y├╝kle</span>
                    <input 
                      type="file" 
                      accept="image/*" 
                      multiple 
                      className="hidden" 
                      onChange={handleImageChange}
                    />
                  </label>
                )}
              </div>
            </div>

            <DialogFooter className="mt-2">
              <Button type="submit" disabled={feedbackLoading} className="bg-blue-600 hover:bg-blue-700 text-white w-full">
                {feedbackLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                G├Ânder
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </>
  );
};

export default AdminSidebar;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Dialog, DialogContent, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Checkbox } from "@/components/ui/checkbox";
import { supabase } from '@/lib/customSupabaseClient';
import { useAuth } from '@/contexts/SupabaseAuthContext';
import { useToast } from '@/components/ui/use-toast';
import { Loader2, Lock, Mail, Phone, User, Building2, ArrowLeft, KeyRound, ArrowRight } from 'lucide-react';
import { TERMS_CONTENT, KVKK_CONTENT } from '@/constants/legalTexts';

const CUSTOMER_LOGO_URL = "faviconbeyaz.png";
const ADMIN_LOGO_URL = "faviconmain.png";

const translateError = (errorMsg) => {
  if (!errorMsg) return "Bir hata olu┼ştu.";
  if (errorMsg.includes("Invalid login credentials")) return "E-posta veya ┼şifre hatal─▒.";
  if (errorMsg.includes("User already registered")) return "Bu e-posta adresi zaten kay─▒tl─▒.";
  if (errorMsg.includes("Password should be at least")) return "┼Şifre en az 6 karakter olmal─▒d─▒r.";
  if (errorMsg.includes("manager code")) return "Ge├ğersiz veya kullan─▒lm─▒┼ş y├Ânetici kodu.";
  if (errorMsg.includes("Database error")) return "Sistem hatas─▒. L├╝tfen y├Ânetici kodunu kontrol edin."; // Veritaban─▒ hatas─▒ ├ğevirisi eklendi
  return "─░┼şlem s─▒ras─▒nda bir hata olu┼ştu. L├╝tfen tekrar deneyin.";
};

// ­şşó Title Case D├Ân├╝┼şt├╝r├╝c├╝ Fonksiyonu - T├╝rk├ğe Karakterleri Destekler
const toTitleCase = (str) => {
  if (!str) return '';
  return str
    .replace(/^\s+/, '') // Ba┼ş─▒ndaki bo┼şluklar─▒ kald─▒r
    .toLowerCase()
    .split(/\s+/) // Bo┼şluklara g├Âre b├Âl
    .map(word => {
      if (!word) return word; // Bo┼ş string'i koru
      return word.charAt(0).toUpperCase() + word.slice(1);
    })
    .join(' '); // Bo┼şluklarla birle┼ştir
};

// Ô£à Legal Modal Component
function LegalModal({ open, onOpenChange, activeLegalTab, setActiveLegalTab, legalAccepted, setLegalAccepted }) {
  if (!open) return null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-[#0f172a] border-slate-700 text-white sm:max-w-[600px] max-h-[85vh] overflow-y-auto">
        <div className="sr-only">
          <DialogTitle>Yasal Bilgilendirme</DialogTitle>
          <DialogDescription>Kullan─▒m Ko┼şullar─▒ ve KVKK Metinleri</DialogDescription>
        </div>
        <div className="mb-4">
          <h3 className="text-xl font-bold text-white">Yasal Bilgilendirme</h3>
        </div>
        <Tabs value={activeLegalTab} onValueChange={setActiveLegalTab} className="w-full">
          <TabsList className="grid w-full grid-cols-2 bg-slate-800">
            <TabsTrigger value="terms" className="data-[state=active]:bg-slate-700 data-[state=active]:text-white">
              Kullan─▒m Ko┼şullar─▒
            </TabsTrigger>
            <TabsTrigger value="kvkk" className="data-[state=active]:bg-slate-700 data-[state=active]:text-white">
              KVKK & Gizlilik
            </TabsTrigger>
          </TabsList>
          <div className="mt-4 p-4 bg-slate-900/50 rounded-lg border border-slate-800 text-sm text-slate-300 leading-relaxed whitespace-pre-wrap font-sans text-justify max-h-96 overflow-y-auto">
            {activeLegalTab === 'terms' ? TERMS_CONTENT : KVKK_CONTENT}
          </div>
        </Tabs>
        <div className="flex justify-end gap-2 mt-6">
          <Button
            variant="ghost"
            onClick={() => onOpenChange(false)}
            className="bg-slate-700 hover:bg-slate-600 text-white"
          >
            Kapat
