        </div>
      </DialogContent>
    </Dialog>
  );
}

// Ô£à Main AuthModal
export default function AuthModal({
  isOpen,
  onClose,
  defaultTab = "login",
  defaultRole = "customer",
  showGuestOption = false,
  onGuestContinue
}) {
  const [activeTab, setActiveTab] = useState(defaultTab);
  const [viewMode, setViewMode] = useState('auth');
  const [activeRole, setActiveRole] = useState(defaultRole);
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    phone: '',
    password: '',
    managerCode: ''
  });

  const [legalAccepted, setLegalAccepted] = useState(false);
  const [showLegalModal, setShowLegalModal] = useState(false);
  const [activeLegalTab, setActiveLegalTab] = useState('terms');

  const navigate = useNavigate();
  const { toast } = useToast();
  const { loginAsGuest } = useAuth();

  useEffect(() => {
    if (isOpen) {
      setActiveTab(defaultTab);
      setActiveRole(defaultRole);
      setViewMode('auth');
      setFormData({ fullName: '', email: '', phone: '', password: '', managerCode: '' });
      setLegalAccepted(false);
    }
  }, [isOpen, defaultTab, defaultRole]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    // ­şşó fullName i├ğin: yazarken Title Case g├Âster
    if (name === 'fullName') {
      // E─şer son karakteri bo┼şluk ise, otomatik formatla
      if (value.endsWith(' ')) {
        // Bo┼şluk eklendiyse, ├Ânceki kelimeyi Title Case yap
        const formatted = toTitleCase(value.slice(0, -1)); // Son bo┼şlu─şu ├ğ─▒kar
        setFormData(prev => ({ ...prev, [name]: formatted + ' ' })); // Tekrar bo┼şluk ekle
      } else {
        setFormData(prev => ({ ...prev, [name]: value }));
      }
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const validatePhone = (phone) => /^05\d{9}$/.test(phone.replace(/\s/g, ''));

  const validateFullName = (fullName) => {
    const parts = fullName.trim().split(' ').filter(p => p.length > 0);
    return parts.length >= 2;
  };

  const validatePassword = (password) => {
    return password.length >= 6 && password.length <= 12;
  };

  const splitName = (fullName) => {
    const parts = fullName.trim().split(' ').filter(p => p.length > 0);
    const last = parts.pop();
    const first = parts.join(' ');
    return { first, last };
  };

  const openLegal = (tab) => {
    setActiveLegalTab(tab);
    setShowLegalModal(true);
  };

  const handleGuestLogin = async () => {
    if (onGuestContinue) {
      onGuestContinue();
    } else {
      await loginAsGuest();
      // loginAsGuest zaten localStorage set ediyor

      toast({
        title: "Misafir Giri┼şi Ba┼şar─▒l─▒",
        description: "Y├Ânlendiriliyorsunuz...",
        className: "bg-teal-600 text-white border-none"
      });

      onClose();

      setTimeout(() => {
        navigate('/customer-panel?guest=true', { replace: true });
      }, 300);
    }
  };

  const handleForgotPassword = async (e) => {
    e.preventDefault();
    if (!formData.email) {
      toast({ title: "Hata", description: "L├╝tfen e-posta adresinizi girin.", variant: "destructive" });
      return;
    }
    setIsLoading(true);
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(formData.email, {
        redirectTo: `${window.location.origin}/update-password`,
      });

      if (error) throw error;

      toast({
        title: "E-posta G├Ânderildi",
        description: "┼Şifre s─▒f─▒rlama ba─şlant─▒s─▒ e-posta adresinize g├Ânderildi. L├╝tfen spam kutunuzu da kontrol edin.",
        className: "bg-teal-600 text-white border-none"
      });

      setViewMode('auth');
      setActiveTab('login');
      setFormData(prev => ({ ...prev, email: '' }));
    } catch (error) {
      console.error("Password reset error:", error);
      toast({ title: "Hata", description: translateError(error.message), variant: "destructive" });
    } finally {
      setIsLoading(false);
    }
  };

  const handleAuth = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      if (activeTab === 'login') {
        const { data, error } = await supabase.auth.signInWithPassword({
          email: formData.email,
          password: formData.password,
        });

        if (error) throw error;

        toast({
          title: "Giri┼ş Ba┼şar─▒l─▒",
          description: "Ho┼ş geldiniz! Y├Ânlendiriliyorsunuz...",
          className: "bg-teal-600 text-white border-none"
        });

        onClose();
        setTimeout(() => {
          if (data.user?.user_metadata?.user_type === 'manager') {
            navigate('/admin-panel', { replace: true });
          } else {
            navigate('/customer-panel', { replace: true });
          }
        }, 300);
      }
      else {
        if (!legalAccepted) {
          toast({ title: "Hata", description: "L├╝tfen yasal metinleri onaylay─▒n─▒z.", variant: "destructive" });
          setIsLoading(false);
          return;
        }

        if (!validateFullName(formData.fullName)) {
          toast({ title: "Hata", description: "L├╝tfen isim ve soyisim giriniz (├Ârn: Emir Y─▒lmaz).", variant: "destructive" });
          setIsLoading(false);
          return;
        }

        if (!validatePassword(formData.password)) {
          toast({ title: "Hata", description: "┼Şifre 6-12 karakter aras─▒nda olmal─▒d─▒r.", variant: "destructive" });
          setIsLoading(false);
          return;
        }

        if (!validatePhone(formData.phone)) {
          toast({ title: "Hata", description: "Telefon numaras─▒ 05xxxxxxxxx format─▒nda olmal─▒d─▒r (11 haneli).", variant: "destructive" });
          setIsLoading(false);
          return;
        }

        // AuthModal.jsx i├ğindeki signUp k─▒sm─▒n─▒ bu kesin haliyle g├╝ncelleyin:
        const { first, last } = splitName(formData.fullName); // fullName'den ay─▒r─▒yoruz

        const { data: signupData, error: signupError } = await supabase.auth.signUp({
          email: formData.email,
          password: formData.password,
          options: {
            data: {
              first_name: first, // splitName'den gelen
              last_name: last,   // splitName'den gelen
              full_name: formData.fullName,
              phone: formData.phone,
              user_type: activeRole, // "manager" olmal─▒
              invite_code: formData.managerCode
            }
          }
        });

        if (signupError) throw signupError;

        if (signupData.session) {
          toast({
            title: "Kay─▒t Ba┼şar─▒l─▒",
            description: "Hesab─▒n─▒z olu┼şturuldu, y├Ânlendiriliyorsunuz...",
            className: "bg-teal-600 text-white border-none"
          });

          onClose();

          setTimeout(() => {
            if (activeRole === 'manager') {
              navigate('/admin-panel', { replace: true });
            } else {
              navigate('/customer-panel', { replace: true });
            }
          }, 800);
        } else {
          toast({
            title: "Kay─▒t Ba┼şar─▒l─▒",
            description: "L├╝tfen e-posta adresinizi do─şrulay─▒n. Gelen kutunuzu kontrol edin.",
            className: "bg-teal-600 text-white border-none"
          });
          onClose();
        }
      }
    } catch (error) {
      console.error("Auth error:", error);
      toast({ title: "Hata", description: translateError(error.message), variant: "destructive" });
    } finally {
      setIsLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <>
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="bg-[#0f172a] border-slate-700 text-white w-[95vw] max-w-md p-0 max-h-[85vh] flex flex-col rounded-xl md:rounded-lg overflow-hidden gap-0">
          <div className="sr-only">
            <DialogTitle>{activeTab === 'login' ? 'Giri┼ş Yap' : 'Kay─▒t Ol'}</DialogTitle>
            <DialogDescription>Giri┼ş yap veya yeni hesap olu┼ştur.</DialogDescription>
          </div>
          <div className="relative flex-shrink-0">
            {/* Header: Mobilde K├╝├ğ├╝lt├╝ld├╝ (h-28), Masa├╝st├╝nde Normal (h-40) */}
            <div className="relative h-24 md:h-40 bg-gradient-to-br from-slate-800 to-slate-900 flex items-center justify-center overflow-hidden transition-all duration-300">
              <div className="absolute inset-0 opacity-20">
                <div className="absolute top-0 right-0 w-32 h-32 bg-orange-500/20 rounded-full blur-2xl" />
                <div className="absolute bottom-0 left-0 w-32 h-32 bg-teal-500/20 rounded-full blur-2xl" />
              </div>
              <img
                src={activeRole === 'customer' ? CUSTOMER_LOGO_URL : ADMIN_LOGO_URL}
                alt="Logo"
                className="h-14 md:h-20 relative z-10 transition-all duration-300"
                style={activeRole === 'manager' ? {
                  filter: 'brightness(0) saturate(100%) invert(64%) sepia(88%) saturate(402%) hue-rotate(132deg) brightness(95%) contrast(91%)'
                } : {}}
              />
            </div>
          </div>

          {/* Content Container - Scrollable Area */}
          <div className="flex-1 p-5 md:p-6 space-y-4 overflow-y-auto overscroll-y-contain">
            {viewMode === 'forgot-password' ? (
              <form onSubmit={handleForgotPassword} className="space-y-4">
                <button
                  type="button"
                  onClick={() => setViewMode('auth')}
                  className="inline-flex items-center gap-2 text-sm text-slate-400 hover:text-white transition-colors mb-2"
                >
                  <ArrowLeft className="h-4 w-4" />
                  Geri D├Ân
                </button>
                <div className="relative">
                  <Mail className="absolute left-3 top-3 h-4 w-4 text-slate-400" />
                  <Input
                    name="email"
                    type="email"
                    placeholder="E-posta Adresi"
                    autoComplete="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    className="pl-10 h-11 bg-slate-800 border-slate-700 text-white focus-visible:ring-teal-500 transition-all"
                    required
                  />
                </div>

                <Button
                  type="submit"
                  disabled={isLoading}
                  className="w-full h-11 bg-teal-600 hover:bg-teal-700 text-white font-bold transition-all"
                >
                  {isLoading ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin mr-2" />
                      G├Ânderiliyor...
                    </>
                  ) : (
                    <>
                      <KeyRound className="h-4 w-4 mr-2" />
                      S─▒f─▒rlama Ba─şlant─▒s─▒ G├Ânder
                    </>
                  )}
                </Button>
              </form>
            ) : (
              <>
                <Tabs value={activeRole} onValueChange={setActiveRole} className="w-full mb-4">
                  <TabsList className="grid w-full grid-cols-2 bg-slate-800/50 p-1">
                    <TabsTrigger value="customer" className="data-[state=active]:bg-orange-600 data-[state=active]:text-white transition-colors duration-300">M├╝┼şteri</TabsTrigger>
                    <TabsTrigger value="manager" className="data-[state=active]:bg-teal-600 data-[state=active]:text-white transition-colors duration-300">Y├Ânetici</TabsTrigger>
                  </TabsList>
                </Tabs>

                <div className="flex bg-slate-800 rounded-lg p-1 gap-1 mb-4">
                  <button onClick={() => setActiveTab('login')} className={`flex-1 px-3 py-2 text-sm rounded-md transition-colors font-medium duration-200 ${activeTab === 'login' ? 'bg-slate-600 text-white' : 'text-slate-400 hover:text-white'}`}>Giri┼ş</button>
                  <button onClick={() => setActiveTab('register')} className={`flex-1 px-3 py-2 text-sm rounded-md transition-colors font-medium duration-200 ${activeTab === 'register' ? 'bg-slate-600 text-white' : 'text-slate-400 hover:text-white'}`}>Kay─▒t Ol</button>
                </div>

                <form onSubmit={handleAuth} className="space-y-4">

                  {/* Misafir Giri┼şi Kutusu */}
                  {showGuestOption && activeRole === 'customer' && (
                    <div className="animate-in fade-in slide-in-from-top-2">
                      <div className="bg-gradient-to-r from-slate-800 to-slate-900 border border-slate-700/60 rounded-xl p-4 shadow-lg mb-6 flex flex-col gap-3">
                        <div className="flex items-center justify-between gap-2">
                          <div className="text-sm text-slate-300 font-medium leading-tight">
                            ├£yelikle u─şra┼şmak <br className="hidden sm:block" /> istemiyor musun?
                          </div>
                          <Button
                            type="button"
                            onClick={handleGuestLogin}
                            size="sm"
                            className="bg-teal-600 hover:bg-teal-700 text-white font-semibold transition-all duration-200 whitespace-nowrap h-10 px-5 shadow-md shadow-teal-900/20 shrink-0"
                          >
                            Misafir Giri┼şi <ArrowRight className="ml-1.5 h-4 w-4" />
                          </Button>
                        </div>
                        <div className="border-t border-slate-700/50 pt-2">
                          <p className="text-[10px] text-slate-500 text-center leading-relaxed">
                            Devam ederek <span className="cursor-pointer hover:text-teal-400 underline decoration-slate-600 underline-offset-2 transition-colors" onClick={(e) => { e.preventDefault(); openLegal('terms'); }}>Kullan─▒m Ko┼şullar─▒</span> ve <span className="cursor-pointer hover:text-teal-400 underline decoration-slate-600 underline-offset-2 transition-colors" onClick={(e) => { e.preventDefault(); openLegal('kvkk'); }}>KVKK Metni</span>'ni kabul etmi┼ş say─▒l─▒rs─▒n─▒z.
                          </p>
                        </div>
                      </div>

