import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { useToast } from "@/components/ui/use-toast";
import { supabase } from '@/lib/customSupabaseClient';
import { useAuth } from '@/contexts/SupabaseAuthContext';
import {
  User, Mail, Phone, Calendar, Star,
  AlertTriangle, Crown, Save, Loader2, MapPin, StickyNote, Filter, FileText, Trash2,
  Image as ImageIcon, RefreshCw, CheckSquare, Square, CheckCircle2, ListChecks // <-- ListChecks Eklendi
} from 'lucide-react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { formatCustomerName } from "@/lib/utils";
import FeedbackDetailModal from './FeedbackDetailModal';

const CustomerProfileModal = ({ isOpen, onClose, customerProfileId, customerEmail, businessId, onFlagsUpdate }) => {
  const { toast } = useToast();
  const { user } = useAuth();

  const [loading, setLoading] = useState(true);
  const [retrying, setRetrying] = useState(false);
  const [profile, setProfile] = useState(null);
  const [feedbacks, setFeedbacks] = useState([]);
  const [flagUpdaterInfo, setFlagUpdaterInfo] = useState(null);

  const [notes, setNotes] = useState('');
  const [isSavingNotes, setIsSavingNotes] = useState(false);
  const [flags, setFlags] = useState({ vip: false, sensitive: false });

  const [detailFeedback, setDetailFeedback] = useState(null);
  const [filterType, setFilterType] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');
  const [showNotesOnly, setShowNotesOnly] = useState(false);
  const [selectedIds, setSelectedIds] = useState([]);

  // RETRY LOGIC
  const fetchAttemptRef = useRef(0);
  const maxRetries = 3;

  // Ô£à D├£ZELT─░LD─░: Anonim kullan─▒c─▒lar i├ğin "Identifier" zorunlulu─şu kald─▒r─▒ld─▒
  const canFetchData = useMemo(() => {
    const hasBusinessId = !!businessId;
    const hasUser = !!user;

    return hasBusinessId && hasUser;
  }, [businessId, user]);

  useEffect(() => {
    if (isOpen) {
      setLoading(true);
      setFeedbacks([]);
      setProfile(null);
      setFilterType('all');
      setFilterStatus('all');
      setShowNotesOnly(false);
      fetchAttemptRef.current = 0;

      if (canFetchData) {
        fetchData();
      } else {
        const timer = setTimeout(() => {
          const checkBusinessId = !!businessId;
          const checkUser = !!user;

          if (checkBusinessId && checkUser) {
            fetchData();
          } else {
            setLoading(false);
            toast({
              variant: "destructive",
              title: "Hata",
              description: "Oturum bilgileri eksik. L├╝tfen sayfay─▒ yenileyin."
            });
          }
        }, 300);

        return () => clearTimeout(timer);
      }
    }
  }, [isOpen, customerProfileId, customerEmail, businessId, canFetchData, user]);

  // MOB─░L GER─░ TU┼ŞU Y├ûNET─░M─░
  useEffect(() => {
    if (!isOpen) return;

    const handlePopState = () => {
      onClose();
    };

    window.history.pushState({ customerModal: true }, '');
    window.addEventListener('popstate', handlePopState);

    return () => window.removeEventListener('popstate', handlePopState);
  }, [isOpen, onClose]);

  const fetchData = useCallback(async () => {
    if (!businessId || !user) {
      setLoading(false);
      return;
    }

    fetchAttemptRef.current += 1;

    try {
      let profileData = null;
      let userData = null;

      // 1. Profile ID ile ara
      if (customerProfileId && customerProfileId !== 'guest') {
        const { data, error } = await supabase
          .from('customer_profiles')
          .select('*, users(first_name, last_name)')
          .eq('id', customerProfileId)
          .maybeSingle();

        if (!error && data) {
          profileData = data;
        }
      }

      // 2. Email ile ara (profile bulunamad─▒ysa)
      if (!profileData && customerEmail) {
        const { data, error } = await supabase
          .from('customer_profiles')
          .select('*, users(first_name, last_name)')
          .eq('email', customerEmail)
          .maybeSingle();

        if (!error && data) {
          profileData = data;
        }
      }

      // 3. Users tablosunda ara (Kay─▒tl─▒ ama profili olu┼şmam─▒┼şsa)
      if (!profileData && customerEmail) {
        const { data, error } = await supabase
          .from('users')
          .select('*')
          .eq('email', customerEmail)
          .eq('user_type', 'customer')
          .maybeSingle();

        if (!error && data) {
          userData = data;
        }
      }

      // 4. Feedbacks ├ğek (Sadece bu i┼şletmeye ait)
      let queryConditions = [];
      if (profileData?.id) queryConditions.push(`customer_profile_id.eq.${profileData.id}`);
      if (customerEmail) queryConditions.push(`customer_email.eq.${customerEmail}`);

      let feedbackData = [];

      // CustomerProfileModal.jsx - fetchData i├ğindeki feedbacks sorgusunu (sat─▒r 152-166) bu hale getirin:

      // fetchData fonksiyonu i├ğindeki feedback sorgusunu bulun:
      // fetchData i├ğindeki feedback sorgusunu ┼şu kesin yap─▒yla g├╝ncelleyin:
      if (queryConditions.length > 0) {
        const { data, error } = await supabase
          .from('feedbacks')
          .select(`
      *,
      branches (id, branch_name_tr),
      customer_profiles (id, admin_note)
    `)
          .eq('business_id', businessId) // ­şÜ® Sadece bu i┼şletme
          .ilike('customer_email', customerEmail) // ­şÜ® Email e┼şle┼şmesi (Duyars─▒z)
          .order('created_at', { ascending: false });

        if (!error) {
          setFeedbacks(data || []);
        }
      }

      const phoneFromHistory = feedbackData?.find(f => f.customer_phone)?.customer_phone || null;

      // 5. ─░┼ŞLETME ├ûZEL VER─░S─░N─░ ├çEK (Business Customers Tablosu)
      let businessSpecificData = null;
      if (profileData?.id && businessId) {
        const { data: bData } = await supabase
          .from('business_customers')
          .select('*')
          .eq('business_id', businessId)
          .eq('customer_profile_id', profileData.id)
          .maybeSingle();

        businessSpecificData = bData;
      }

      // 6. Profile state'i set et
      if (profileData) {
        const uFirst = profileData.users?.first_name || '';
        const uLast = profileData.users?.last_name || '';
        const rawName = uFirst ? `${uFirst} ${uLast}`.trim() : profileData.name;

        setProfile({
          ...profileData,
          formattedName: formatCustomerName(rawName),
          phone: profileData.phone || phoneFromHistory || '-',
          is_virtual: false
        });

        // Verileri i┼şletme tablosundan (business_customers) al, yoksa varsay─▒lan bo┼ş.
        setNotes(businessSpecificData?.manager_notes || '');
        setFlags({
          vip: businessSpecificData?.is_vip || false,
          sensitive: businessSpecificData?.is_sensitive || false
        });

        if (profileData.flag_updated_by) {
          const { data: updater } = await supabase
            .from('users')
            .select('first_name, last_name')
            .eq('id', profileData.flag_updated_by)
            .single();

          if (updater) {
            setFlagUpdaterInfo(`${updater.first_name} ${updater.last_name || ''}`.trim() +
              ` - ${new Date(profileData.flag_updated_at).toLocaleDateString('tr-TR')}`);
          }
        }
      } else {
        // Virtual profile olu┼ştur
        const nameSource = userData || {
          first_name: customerEmail?.split('@')[0] || 'Misafir',
          last_name: ''
        };
        const rawName = `${nameSource.first_name} ${nameSource.last_name || ''}`.trim();

        setProfile({
          id: null,
          user_id: userData?.id || null,
          email: customerEmail,
          name: rawName,
          formattedName: formatCustomerName(rawName),
          phone: userData?.phone || phoneFromHistory || '-',
          created_at: userData?.created_at || new Date().toISOString(),
          is_virtual: true
        });
        setNotes('');
        setFlags({ vip: false, sensitive: false });
      }

      setLoading(false);
      fetchAttemptRef.current = 0;

    } catch (error) {
      console.error('ÔØî fetchData kritik hata:', error);

      if (fetchAttemptRef.current < maxRetries) {
        setRetrying(true);
        setTimeout(() => {
          setRetrying(false);
          fetchData();
        }, 1000 * fetchAttemptRef.current);
      } else {
        setLoading(false);
        toast({
          variant: "destructive",
          title: "Veri Y├╝klenemedi",
          description: "M├╝┼şteri bilgileri y├╝klenemedi. L├╝tfen modal─▒ kapat─▒p tekrar a├ğ─▒n."
        });
      }
    }
  }, [businessId, customerEmail, customerProfileId, user, toast]);

  const saveChanges = async (newFlags = flags, newNote = notes) => {
    if (!profile || !user) return;

    setIsSavingNotes(true);

    try {
      const now = new Date().toISOString();
      let targetProfileId = profile.id;

      // 1. E─şer profil sanalsa (virtual), ├Ânce customer_profiles'a kaydet
      if (profile.is_virtual) {
        const { data: newProfile, error } = await supabase
          .from('customer_profiles')
          .insert({
            user_id: profile.user_id,
            email: profile.email,
            name: profile.name,
            phone: profile.phone === '-' ? null : profile.phone,
            created_at: now,
            updated_at: now
          })
          .select()
          .single();

        if (error) throw error;

        targetProfileId = newProfile.id;
        setProfile(prev => ({ ...prev, ...newProfile, is_virtual: false }));

        // Feedbackleri yeni profile ba─şla
        if (profile.email) {
          await supabase
            .from('feedbacks')
            .update({ customer_profile_id: targetProfileId })
            .eq('customer_email', profile.email)
            .eq('business_id', businessId);
        }
      }

      // 2. ─░┼şletmeye ├ûzel Tabloya Kaydet (business_customers)
      const { error: bizError } = await supabase
        .from('business_customers')
        .upsert({
          business_id: businessId,
          customer_profile_id: targetProfileId,
          is_vip: newFlags.vip,
          is_sensitive: newFlags.sensitive,
          manager_notes: newNote,
          last_interaction_at: now,
          updated_at: now
        }, { onConflict: 'business_id, customer_profile_id' });

      if (bizError) throw bizError;

      toast({
        title: "Kaydedildi",
        className: "bg-green-600 text-white border-none"
      });

      if (onFlagsUpdate) {
        onFlagsUpdate(targetProfileId, {
          vip: newFlags.vip,
          sensitive: newFlags.sensitive,
          admin_note: newNote
        }, profile.email);
      }

      const userName = user.user_metadata?.first_name || 'Siz';
      setFlagUpdaterInfo(`${userName} - ${new Date().toLocaleDateString('tr-TR')}`);

    } catch (e) {
      console.error('ÔØî saveChanges hatas─▒:', e);
      toast({
        variant: "destructive",
        title: "Hata",
        description: e.message
      });
    } finally {
      setIsSavingNotes(false);
    }
  };

  const handleToggleVip = (val) => {
    const next = { ...flags, vip: val, sensitive: val ? false : flags.sensitive };
    setFlags(next);
    saveChanges(next, notes);
  };

  const handleToggleSensitive = (val) => {
    const next = { ...flags, sensitive: val, vip: val ? false : flags.vip };
    setFlags(next);
    saveChanges(next, notes);
  };

  const handleRetry = () => {
    fetchAttemptRef.current = 0;
    setLoading(true);
    fetchData();
  };

  const handleClose = () => {
    if (window.history.state?.customerModal) {
      window.history.back();
    } else {
      onClose();
    }
  };

  const getTypeBadge = (type) => {
    const styles = {
      complaint: "text-red-400 bg-red-900/20 border-red-900/30",
      suggestion: "text-blue-400 bg-blue-900/20 border-blue-900/30",
      evaluation: "text-yellow-400 bg-yellow-900/20 border-yellow-900/30",
      review: "text-yellow-400 bg-yellow-900/20 border-yellow-900/30",
      rating: "text-yellow-400 bg-yellow-900/20 border-yellow-900/30"
    };
    const labels = {
      complaint: "┼Şikayet",
      suggestion: "├ûneri",
      evaluation: "De─şerlendirme",
      review: "De─şerlendirme",
      rating: "De─şerlendirme"
    };
    return (
      <Badge variant="secondary" className={`text-[10px] px-2 py-0.5 ${styles[type] || "text-slate-400"}`}>
        {labels[type] || type}
      </Badge>
    );
  };

  const getStatusBadge = (status) => {
    const styles = {
      new: "bg-cyan-500/10 text-cyan-500 border-cyan-500/20",
      pending: "bg-indigo-500/10 text-indigo-500 border-indigo-500/20",
      in_progress: "bg-yellow-500/10 text-yellow-500 border-yellow-500/20",
      resolved: "bg-green-500/10 text-green-500 border-green-500/20",
      escalated: "bg-red-500/10 text-red-500 border-red-500/20"
    };
    const labels = {
      new: "Yeni",
      pending: "Beklemede",
      in_progress: "─░┼şlemde",
      resolved: "├ç├Âz├╝ld├╝",
      escalated: "Acil"
    };
    return (
      <Badge variant="outline" className={`text-[10px] h-5 px-1.5 whitespace-nowrap ${styles[status] || "text-slate-500"}`}>
        {labels[status] || status}
      </Badge>
    );
  };

  const hasImages = (f) => (
    (f.feedback_images && f.feedback_images.length > 0) ||
    (f.receipt_images && f.receipt_images.length > 0)
  );

  const filteredList = useMemo(() => {
    return feedbacks.filter(f => {
      if (filterType !== 'all') {
        if (filterType === 'evaluation') {
          if (!['evaluation', 'review', 'rating'].includes(f.feedback_type)) return false;
        } else {
          if (f.feedback_type !== filterType) return false;
        }
      }
      if (filterStatus !== 'all' && f.status !== filterStatus) return false;
      if (showNotesOnly && !f.manager_note) return false;
      return true;
    });
  }, [feedbacks, filterType, filterStatus, showNotesOnly]);

  // SE├ç─░M VE G├£NCELLEME
  const toggleSelect = (id) => {
    setSelectedIds(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  };

  // ­şşó YEN─░: T├£M├£N├£ SE├ç (Listelenenler)
  const handleSelectAll = () => {
    if (selectedIds.length === filteredList.length) setSelectedIds([]);
    else setSelectedIds(filteredList.map(f => f.id));
  };

  // ­şşó YEN─░: ├çOKLU SE├çENEK G├£NCELLEME
  const handleBulkUpdate = async (status) => {
    if (selectedIds.length === 0) return;
    const updates = { status, resolved_at: status === 'resolved' ? new Date().toISOString() : null };

    const { error } = await supabase.from('feedbacks').update(updates).in('id', selectedIds);
    if (!error) {
      toast({ title: "Ba┼şar─▒l─▒", description: `${selectedIds.length} kay─▒t g├╝ncellendi.`, className: "bg-green-600 text-white border-none" });
      setFeedbacks(prev => prev.map(f => selectedIds.includes(f.id) ? { ...f, ...updates } : f));
      setSelectedIds([]);
    } else { toast({ variant: "destructive", title: "Hata olu┼ştu" }); }
  };

  if (!isOpen) return null;

  return (
    <>
      <Dialog open={isOpen} onOpenChange={handleClose}>
        <DialogContent className="w-[95vw] sm:w-full sm:max-w-2xl max-h-[90vh] flex flex-col bg-slate-900 border border-slate-800 text-slate-100 p-0 gap-0 overflow-hidden">

          <DialogHeader className="px-6 py-4 border-b border-slate-800 flex-shrink-0">
            <DialogTitle className="text-xl font-bold flex items-center gap-2">
              <User className="w-6 h-6 text-indigo-400" /> M├╝┼şteri Profili
            </DialogTitle>
            <DialogDescription className="text-slate-400 text-sm sr-only">
              M├╝┼şteri profil detaylar─▒ ve ge├ğmi┼ş i┼şlemleri.
            </DialogDescription>
          </DialogHeader>

          <div className="flex-1 overflow-y-auto px-4 py-4 sm:px-6 sm:py-6 space-y-6">
            {loading ? (
              <div className="flex flex-col items-center justify-center py-12 gap-4">
                <Loader2 className="w-10 h-10 animate-spin text-indigo-500" />
                <p className="text-slate-400 text-sm">
                  {retrying ? 'Yeniden deneniyor...' : 'M├╝┼şteri bilgileri y├╝kleniyor...'}
                </p>
                {fetchAttemptRef.current > 1 && (
                  <p className="text-slate-500 text-xs">
                    Deneme {fetchAttemptRef.current}/{maxRetries}
                  </p>
                )}
              </div>
            ) : !profile ? (
              <div className="flex flex-col items-center justify-center py-12 gap-4">
                <AlertTriangle className="w-12 h-12 text-red-500" />
                <p className="text-slate-300 text-center">
                  M├╝┼şteri bilgileri y├╝klenemedi
                </p>
                <Button
                  onClick={handleRetry}
                  className="bg-teal-600 hover:bg-teal-700 text-white"
                >
                  <RefreshCw className="w-4 h-4 mr-2" />
                  Tekrar Dene
                </Button>
              </div>
            ) : (
              <>
                {/* Profil Bilgileri */}
                <div className="customer-info-block bg-gradient-to-br from-indigo-900/30 to-purple-900/20 rounded-lg p-5 border border-indigo-700/40 grid md:grid-cols-2 gap-4">
                  <div className="flex items-center gap-3 min-w-0">
                    <User className="w-5 h-5 text-indigo-400 shrink-0" />
                    <div className="min-w-0">
                      <p className="text-xs text-slate-400 uppercase">─░sim</p>
                      <p className="font-semibold truncate">{profile?.formattedName}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3 min-w-0">
                    <Mail className="w-5 h-5 text-blue-400 shrink-0" />
                    <div className="min-w-0 flex-1">
                      <p className="text-xs text-slate-400 uppercase">E-posta</p>
                      <p className="font-semibold text-sm break-all">{profile?.email || '-'}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3 min-w-0">
                    <Phone className="w-5 h-5 text-green-400 shrink-0" />
                    <div className="min-w-0">
                      <p className="text-xs text-slate-400 uppercase">Telefon</p>
                      <p className="font-semibold">{profile?.phone || '-'}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3 min-w-0">
                    <Calendar className="w-5 h-5 text-amber-400 shrink-0" />
                    <div className="min-w-0">
                      <p className="text-xs text-slate-400 uppercase">Kay─▒t</p>
                      <p className="font-semibold">
                        {profile?.created_at ? new Date(profile.created_at).toLocaleDateString('tr-TR') : '-'}
                      </p>
                    </div>
                  </div>
                </div>

                {/* Flags & Notes */}
                <div className="grid md:grid-cols-3 gap-4">
                  <div className="bg-slate-800/40 rounded-lg p-4 border border-slate-700/50 flex flex-col justify-between">
                    <div className="space-y-3">
                      <div className="flex justify-between items-center">
                        <label className="text-sm font-medium text-purple-300 flex gap-2">
                          <Crown className="w-4 h-4" /> VIP
                        </label>
                        <Switch
                          checked={flags.vip}
                          onCheckedChange={handleToggleVip}
                          className="data-[state=checked]:bg-purple-600"
                        />
                      </div>
                      <div className="h-px bg-slate-700/50" />
                      <div className="flex justify-between items-center">
                        <label className="text-sm font-medium text-orange-300 flex gap-2">
                          <AlertTriangle className="w-4 h-4" /> Hassas
                        </label>
                        <Switch
                          checked={flags.sensitive}
                          onCheckedChange={handleToggleSensitive}
                          className="data-[state=checked]:bg-orange-600"
                        />
                      </div>
                    </div>
                    {flagUpdaterInfo && (
                      <div className="mt-4 pt-2 border-t border-slate-700/50 text-[10px] text-slate-500 italic">
                        Son g├╝ncelleyen: {flagUpdaterInfo}
                      </div>
                    )}
                  </div>

                  <div className="md:col-span-2 bg-blue-900/20 rounded-lg p-4 border border-blue-500/30 flex flex-col">
                    <h3 className="text-sm font-semibold text-blue-400 uppercase mb-2 flex gap-2">
                      <FileText className="w-4 h-4" /> ─░┼şletme ├ûzel Notu
                    </h3>
                    <Textarea
                      value={notes}
                      onChange={(e) => setNotes(e.target.value)}
                      className="bg-slate-900/80 border-slate-700 flex-1 min-h-[80px] text-slate-200 focus-visible:ring-2 focus-visible:ring-blue-500"
                      placeholder="Sadece bu i┼şletme y├Âneticileri g├Ârebilir..."
                    />
                    <div className="flex justify-end gap-2 mt-2">
                      {notes && (
                        <Button
                          size="sm"
                          onClick={() => { setNotes(''); saveChanges(flags, ''); }}
                          disabled={isSavingNotes}
                          className="h-7 bg-red-600/90 hover:bg-red-600 text-white border border-red-500/60 font-medium shadow-sm"
                        >
                          <Trash2 className="w-3 h-3 mr-1" /> Sil
                        </Button>
                      )}
                      <Button
                        size="sm"
                        onClick={() => saveChanges(flags, notes)}
                        disabled={isSavingNotes}
                        className="h-7 bg-blue-600 hover:bg-blue-700 text-white font-semibold border border-blue-500/50 shadow-md"
                      >
                        {isSavingNotes ? <Loader2 className="w-3 h-3 animate-spin" /> : <Save className="w-3 h-3 mr-1" />}
                        Kaydet
                      </Button>
                    </div>
                  </div>
                </div>

                {/* Feedback History */}
                <div>
                  <div className="flex flex-col gap-3 mb-4">
                    <div className="flex justify-between items-center mb-2">
                      <h3 className="text-lg font-bold text-white">Geri Bildirim Ge├ğmi┼şi ({filteredList.length})</h3>
                      {filteredList.length > 0 && (
                        <Button variant="ghost" size="sm" onClick={handleSelectAll} className="h-6 text-xs text-slate-400 hover:text-white">
                          {selectedIds.length === filteredList.length ? 'Se├ğimi Kald─▒r' : 'T├╝m├╝n├╝ Se├ğ'}
                        </Button>
                      )}
                    </div>

                    <div className="flex flex-wrap gap-2 items-center w-full">
                      <Select value={filterType} onValueChange={setFilterType}>
                        <SelectTrigger className="w-[120px] h-8 text-xs bg-slate-800 border-slate-700">
                          <span className="truncate">
                            {filterType === 'all' ? 'T├╝m├╝' :
                              filterType === 'complaint' ? '┼Şikayet' :
                                filterType === 'suggestion' ? '├ûneri' : 'De─şerlendirme'}
                          </span>
                        </SelectTrigger>
                        <SelectContent className="bg-slate-800 border-slate-700">
                          <SelectItem value="all">T├╝m├╝</SelectItem>
                          <SelectItem value="complaint">┼Şikayet</SelectItem>
                          <SelectItem value="suggestion">├ûneri</SelectItem>
                          <SelectItem value="evaluation">De─şerlendirme</SelectItem>
                        </SelectContent>
                      </Select>

                      <Select value={filterStatus} onValueChange={setFilterStatus}>
                        <SelectTrigger className="w-[120px] h-8 text-xs bg-slate-800 border-slate-700">
                          <span className="truncate">
                            {filterStatus === 'all' ? 'T├╝m Durumlar' :
                              filterStatus === 'new' ? 'Yeni' :
                                filterStatus === 'pending' ? 'Beklemede' :
                                  filterStatus === 'in_progress' ? '─░┼şlemde' :
                                    filterStatus === 'escalated' ? 'Acil' : '├ç├Âz├╝ld├╝'}
                          </span>
                        </SelectTrigger>
                        <SelectContent className="bg-slate-800 border-slate-700">
                          <SelectItem value="all">T├╝m├╝</SelectItem>
                          <SelectItem value="new">Yeni</SelectItem>
                          <SelectItem value="pending">Beklemede</SelectItem>
                          <SelectItem value="in_progress">─░┼şlemde</SelectItem>
                          <SelectItem value="escalated">Acil</SelectItem>
                          <SelectItem value="resolved">├ç├Âz├╝ld├╝</SelectItem>
                        </SelectContent>
                      </Select>

                      <div className="flex items-center space-x-2 bg-slate-800/50 px-2 py-1.5 rounded-md border border-slate-700 h-8">
                        <Checkbox
                          id="notes-filter-modal"
                          checked={showNotesOnly}
                          onCheckedChange={setShowNotesOnly}
                          className="border-slate-500 data-[state=checked]:bg-indigo-500 data-[state=checked]:border-indigo-500 w-4 h-4"
                        />
                        <label
                          htmlFor="notes-filter-modal"
                          className="text-xs font-medium leading-none text-slate-300 cursor-pointer select-none flex items-center gap-1"
                        >
                          <StickyNote className="w-3 h-3 text-amber-400" /> Notlu
                        </label>
                      </div>
                    </div>
                  </div>

                  {selectedIds.length > 0 && (
                    <div className="bg-indigo-900/40 border border-indigo-500/50 p-2 rounded-lg flex flex-col sm:flex-row items-center justify-between mb-3 animate-in fade-in slide-in-from-top-2 gap-2">
                      <span className="text-sm text-indigo-200 font-medium ml-2">{selectedIds.length} se├ğildi</span>
                      <div className="flex gap-2">
                        <Button size="sm" onClick={() => handleBulkUpdate('pending')} variant="ghost" className="h-7 text-xs text-indigo-300 hover:text-white hover:bg-indigo-800">Bekle</Button>
                        <Button size="sm" onClick={() => handleBulkUpdate('in_progress')} variant="ghost" className="h-7 text-xs text-yellow-300 hover:text-white hover:bg-yellow-800">─░┼şlemde</Button>
                        <Button size="sm" onClick={() => handleBulkUpdate('resolved')} className="h-7 bg-green-600 hover:bg-green-700 text-white border-none text-xs">
                          <CheckCircle2 className="w-3 h-3 mr-1" /> ├ç├Âz├╝ld├╝
                        </Button>
                      </div>
                    </div>
                  )}

                  {filteredList.length === 0 ? (
                    <div className="text-center py-8 border border-dashed border-slate-700/50 rounded-lg">
                      <Filter className="w-8 h-8 text-slate-600 mx-auto mb-2 opacity-50" />
                      <p className="text-slate-500 italic text-sm">Kay─▒t bulunamad─▒.</p>
                    </div>
                  ) : (
                    <div className="space-y-3">
                      {filteredList.map(f => {
                        const rating = f.rating || f.overall_rating;
                        const hasImgs = hasImages(f);
                        const hasManagerNote = !!f.manager_note;
                        const hasComment = (f.message && f.message.trim().length > 0) ||
                          (f.general_eval_comment && f.general_eval_comment.trim().length > 0);

                        return (
                          // 1. YEN─░ DI┼Ş KAPSAYICI (WRAPPER)
                          <div key={f.id} className="flex gap-3 items-start group/item">

                            {/* 2. CHECKBOX BUTONU (YEN─░ EKLENEN KISIM) */}
                            <button
                              onClick={(e) => { e.stopPropagation(); toggleSelect(f.id); }}
                              className="mt-3 text-slate-500 hover:text-indigo-400 transition-colors shrink-0"
                            >
                              {selectedIds.includes(f.id)
                                ? <CheckSquare className="w-5 h-5 text-indigo-500" />
                                : <Square className="w-5 h-5" />}
                            </button>

                            {/* 3. SEN─░N OR─░J─░NAL KARTIN (Sadece flex-1 eklendi) */}
                            <div
                              onClick={() => setDetailFeedback(f)}
                              className="flex-1 group bg-slate-800/40 p-3 rounded-lg border border-slate-700/50 hover:bg-slate-800/80 transition-colors cursor-pointer relative overflow-hidden"
                            >
                              <div className="flex justify-between items-start mb-2">
                                <div className="flex items-center gap-2">
                                  {getTypeBadge(f.feedback_type)}
                                  <span className="text-xs text-slate-400">
                                    {new Date(f.created_at).toLocaleDateString('tr-TR')}
                                  </span>
                                </div>
                                {getStatusBadge(f.status)}
                              </div>

                              {/* KARTIN GER─░ KALAN ─░├çER─░─Ş─░ (MEVCUT KODUN DEVAMI) */}
                              <div className="flex gap-3 items-start">
                                <div className={`mt-1.5 w-1.5 h-1.5 rounded-full shrink-0 ${f.feedback_type === 'complaint' ? 'bg-red-500' :
                                  f.feedback_type === 'suggestion' ? 'bg-blue-500' : 'bg-yellow-500'
                                  }`} />
                                <div className="flex-1 min-w-0">
                                  <p className="text-sm text-slate-300 line-clamp-2 break-words">
                                    {f.message || <span className="italic text-slate-600">Mesaj yok</span>}
                                  </p>

                                  <div className="flex items-center justify-between mt-2 pt-2 border-t border-slate-700/30">
                                    <div className="flex items-center gap-2 min-w-0">
                                      <span className="text-xs text-slate-500 flex items-center gap-1 truncate">
                                        <MapPin className="w-3 h-3 shrink-0" />
                                        {f.branches?.branch_name_tr || '┼Şube Yok'}
                                      </span>
                                      {rating > 0 && (
                                        <div className="flex items-center gap-0.5 text-yellow-500 shrink-0">
                                          {[...Array(5)].map((_, i) => (
                                            <Star
                                              key={i}
                                              className={`w-3 h-3 ${i < rating ? 'fill-current' : 'text-slate-700 fill-none'
                                                }`}
                                            />
                                          ))}
                                        </div>
                                      )}
                                    </div>

                                    <div className="flex items-center gap-1.5 shrink-0">
                                      {hasComment && (
                                        <div className="flex items-center gap-1 px-1.5 py-0.5 bg-slate-700/50 rounded text-[10px] text-blue-400 border border-slate-600/50">
                                          <FileText className="w-3 h-3" />
                                          <span className="hidden sm:inline">Genel D.</span>
                                        </div>
                                      )}
                                      {hasImgs && (
                                        <div
                                          className="flex items-center gap-1 px-1.5 py-0.5 bg-slate-700/50 rounded text-[10px] text-teal-400 border border-slate-600/50"
                                          title="G├Ârsel Var"
                                        >
                                          <ImageIcon className="w-3 h-3" />
                                          <span className="hidden sm:inline">G├Ârsel</span>
                                        </div>
                                      )}
                                      {hasManagerNote && (
                                        <div
                                          className="flex items-center justify-center w-5 h-5 rounded bg-amber-500/20 text-amber-400 border border-amber-500/30"
                                          title="Y├Ânetici Notu Var"
                                        >
                                          <StickyNote className="w-3 h-3 fill-current" />
                                        </div>
                                      )}
                                    </div>
                                  </div>
                                </div>
                              </div>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              </>
            )}
          </div>

          {/* FOOTER */}
          <div className="px-6 py-4 border-t border-slate-800 flex-shrink-0 flex justify-end">
            <Button
              variant="outline"
              onClick={handleClose}
              className="bg-slate-700 border-slate-600 hover:bg-slate-600 text-white font-medium shadow-none ring-0 focus:ring-0 focus-visible:ring-0"
            >
              Kapat
            </Button>
          </div>

        </DialogContent>
      </Dialog>

      {detailFeedback && (
        <FeedbackDetailModal
          isOpen={!!detailFeedback}
          onClose={() => setDetailFeedback(null)}
          feedback={detailFeedback}
          onStatusChange={(id, newStatus) => {
            setFeedbacks(prev => prev.map(f => f.id === id ? { ...f, status: newStatus } : f));
          }}
        />
      )}
    </>
  );
};

