import React, { useState, useEffect } from 'react';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { startOfMonth, endOfMonth } from "date-fns";
import { useAdminContext } from '@/contexts/AdminContext';

const DateRangePicker = ({ className, date, setDate, preset, setPreset }) => {
  const { businessCreatedAt } = useAdminContext();
  const [minDate, setMinDate] = useState(new Date(2020, 0, 1));

  useEffect(() => {
    if (businessCreatedAt) {
      const businessDate = new Date(businessCreatedAt);
      businessDate.setHours(0, 0, 0, 0);
      setMinDate(businessDate);
    }
  }, [businessCreatedAt]);

  const presets = [
    { value: 'daily', label: 'Son 24 Saat' },
    { value: '7days', label: 'Son 7 G├╝n' },
    { value: '30days', label: 'Son 30 G├╝n' },
    { value: 'thisMonth', label: 'Bu Ay' },
    { value: 'lastMonth', label: 'Ge├ğen Ay' },
    { value: '6months', label: 'Son 6 Ay' },
    { value: '12months', label: 'Son 1 Y─▒l' },
    { value: 'allTime', label: 'T├╝m Zamanlar' },
  ];

  const handlePresetChange = (value) => {
    if (setPreset) setPreset(value);
    
    const now = new Date();
    let fromDate = new Date();
    
    // Reset hours to start of day for fromDate
    fromDate.setHours(0, 0, 0, 0);
    // Set to end of day for "now" / "to" date
    now.setHours(23, 59, 59, 999);

    switch (value) {
      case 'daily':
        fromDate.setDate(now.getDate() - 1);
        break;
      case '7days':
        fromDate.setDate(now.getDate() - 7);
        break;
      case '30days':
        fromDate.setDate(now.getDate() - 30);
        break;
      case 'thisMonth':
        fromDate = startOfMonth(now);
        break;
      case 'lastMonth':
        fromDate = startOfMonth(new Date(now.getFullYear(), now.getMonth() - 1, 1));
        now.setTime(endOfMonth(new Date(now.getFullYear(), now.getMonth() - 1, 1)).getTime());
        now.setHours(23, 59, 59, 999);
        break;
      case '6months':
        fromDate.setMonth(now.getMonth() - 6);
        break;
      case '12months':
        fromDate.setFullYear(now.getFullYear() - 1);
        break;
      case 'allTime':
        fromDate = minDate;
        break;
      default:
        break;
    }

    if (fromDate < minDate) {
      fromDate = minDate;
    }

    setDate({ from: fromDate, to: now });
  };

  const selectedLabel = presets.find(p => p.value === preset)?.label;

  return (
    <div className={cn("flex items-center", className)}>
      <Select value={preset} onValueChange={handlePresetChange}>
        <SelectTrigger className="w-full md:w-[180px] bg-slate-800 border-slate-700 text-white h-10">
          <SelectValue placeholder="Zaman Aral─▒─ş─▒">
            {selectedLabel || "Zaman Aral─▒─ş─▒"}
          </SelectValue>
        </SelectTrigger>
        <SelectContent className="bg-slate-800 border-slate-700 text-white">
          {presets.map((p) => (
            <SelectItem key={p.value} value={p.value}>{p.label}</SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
};

export default DateRangePicker;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  X, Star, Calendar, User, Mail, Phone, MessageSquare,
  AlertTriangle, Image as ImageIcon, Building2, StickyNote, Save,
  Loader2, Crown, FileText, Copy, Hash, Download,
  ZoomIn, ChevronLeft, ChevronRight, Siren, Trash2, Lightbulb, Receipt,
  BarChart, ExternalLink
} from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { supabase } from '@/lib/customSupabaseClient';
import { useToast } from "@/components/ui/use-toast";
import { Badge } from "@/components/ui/badge";
import { useAuth } from '@/contexts/SupabaseAuthContext';
import CustomerProfileModal from './CustomerProfileModal';
import { cn, formatCustomerName, getCustomerData } from "@/lib/utils";

const FeedbackDetailModal = ({ feedback, isOpen, onClose, onFeedbackUpdate, onStatusChange, scrollToNotes = false }) => {
  const { toast } = useToast();
  const { user } = useAuth();

  const [isUpdating, setIsUpdating] = useState(false);
  const [isSavingNote, setIsSavingNote] = useState(false);
  const [currentStatus, setCurrentStatus] = useState(feedback?.status || 'new');
  const [managerNote, setManagerNote] = useState('');
  const [lastUpdatedInfo, setLastUpdatedInfo] = useState(null);

  const [customerStats, setCustomerStats] = useState(null);
  const [customerJoinDate, setCustomerJoinDate] = useState(null);
  const [statsLoading, setStatsLoading] = useState(false);
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);

  // Lightbox State
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [lightboxImages, setLightboxImages] = useState([]);

  const [liveProfileData, setLiveProfileData] = useState(null);
  const [businessSpecificData, setBusinessSpecificData] = useState(null);
  const notesSectionRef = useRef(null);

  // --- S├£ZGE├ç (HATA ├ûNLEY─░C─░) ---
  const normalizeUrl = (u) => {
    if (!u) return null;
    const s = String(u).trim();
    if (/^[a-zA-Z]:\\/.test(s) || s.includes("\\")) return null;
    if (s.startsWith("http://") || s.startsWith("https://") || s.startsWith("blob:") || s.startsWith("data:")) return s;
    return null;
  };

  const profileUser = liveProfileData?.users || feedback.customer_profiles?.users;
  const rawName = profileUser ? `${profileUser.first_name} ${profileUser.last_name || ''}` : (liveProfileData?.name || feedback.customer_profiles?.name || feedback.customer_name);
  const formattedName = formatCustomerName(rawName);

  const displayPhone = (liveProfileData?.phone && liveProfileData.phone.length > 3) ? liveProfileData.phone : (feedback.customer_phone || '-');
  const displayEmail = (liveProfileData?.email && liveProfileData.email.length > 3) ? liveProfileData.email : (feedback.customer_email || '-');

  // ­şşó ANON─░M KONTROL├£ (YEN─░ EKLEND─░)
  const isAnonymous = (!feedback.customer_profile_id || feedback.customer_profile_id === 'guest') && (!feedback.customer_email || feedback.customer_email.length < 5);
  const hasProfileId = feedback.customer_profile_id && feedback.customer_profile_id !== 'guest';
  const hasEmail = feedback.customer_email && feedback.customer_email.length > 5;

  const isVip = businessSpecificData?.is_vip || false;
  const isSensitive = businessSpecificData?.is_sensitive || false;
  const customerProfileNote = businessSpecificData?.manager_notes || null;

  const allImages = [
    ...(feedback?.feedback_images || []),
    ...(feedback?.image_urls || []),
    feedback?.product_image_url,
    ...(feedback?.receipt_images || []),
    feedback?.receipt_url
  ].map(normalizeUrl).filter(Boolean);

  const generalRating = Number(feedback.general_eval_rating) || 0;
  const generalComment = feedback.general_eval_comment;
  const hasGeneralEval = generalRating > 0 || (generalComment && generalComment.trim().length > 0);

  useEffect(() => { if (isOpen && scrollToNotes && notesSectionRef.current) setTimeout(() => notesSectionRef.current.scrollIntoView({ behavior: 'smooth', block: 'center' }), 300); }, [isOpen, scrollToNotes]);

  useEffect(() => {
    if (feedback && isOpen) {
      setCurrentStatus(feedback.status);
      setManagerNote(feedback.manager_note || '');
      setLiveProfileData(null);
      setBusinessSpecificData(null);

      // E-posta veya Profil ID varsa veriyi ├ğek
      if (hasProfileId || hasEmail) {
        fetchCustomerData();
      } else {
        setCustomerStats(null);
        setCustomerJoinDate(null);
      }

      if (feedback.manager_note_updated_at && feedback.manager_note_updated_by) fetchUpdaterInfo(feedback.manager_note_updated_by, feedback.manager_note_updated_at);
    }
  }, [feedback, isOpen, isAnonymous]);

  const fetchCustomerData = useCallback(async () => {
    if (isAnonymous && !hasEmail) return; // G├╝venlik ├Ânlemi

    setStatsLoading(true);
    try {
      const cEmail = getCustomerData(feedback, 'email');
      const cProfileId = feedback.customer_profile_id;

      let statsQuery = supabase.from('feedbacks').select('feedback_type', { count: 'exact' }).eq('business_id', feedback.business_id);
      if (cProfileId) statsQuery = statsQuery.eq('customer_profile_id', cProfileId);
      else if (cEmail) statsQuery = statsQuery.eq('customer_email', cEmail);
      else { setStatsLoading(false); return; }

      const { data: statsData } = await statsQuery;
      if (statsData) {
        setCustomerStats({
          total: statsData.length,
          complaints: statsData.filter(f => f.feedback_type === 'complaint').length,
          suggestions: statsData.filter(f => f.feedback_type === 'suggestion').length,
          evaluations: statsData.filter(f => ['evaluation', 'rating', 'review'].includes(f.feedback_type)).length
        });
      }

      let profileData = null;
      if (cProfileId && cProfileId !== 'guest') {
        const { data } = await supabase.from('customer_profiles').select('*, users(first_name, last_name)').eq('id', cProfileId).maybeSingle();
        profileData = data;
      } else if (cEmail) {
        const { data } = await supabase.from('customer_profiles').select('*, users(first_name, last_name)').eq('email', cEmail).maybeSingle();
        profileData = data;
      }

      if (profileData) {
        setLiveProfileData(profileData);
        setCustomerJoinDate(profileData.created_at);

        if (feedback.business_id) {
          const { data: bizData } = await supabase
            .from('business_customers')
            .select('*')
            .eq('business_id', feedback.business_id)
            .eq('customer_profile_id', profileData.id)
            .maybeSingle();

          if (bizData) setBusinessSpecificData(bizData);
        }
      }
    } catch (err) { console.error("Error", err); } finally { setStatsLoading(false); }
  }, [feedback, isAnonymous]);

  const fetchUpdaterInfo = async (userId, updatedAt) => {
    if (!userId) return;
    const { data } = await supabase.from('users').select('first_name, last_name').eq('id', userId).single();
    if (data) setLastUpdatedInfo(`${data.first_name} ${data.last_name || ''} - ${new Date(updatedAt).toLocaleString('tr-TR')}`);
  };

  const handleStatusUpdate = async (newStatus) => {
    setIsUpdating(true);
    try {
      const { error } = await supabase.from('feedbacks').update({ status: newStatus, resolved_at: newStatus === 'resolved' ? new Date().toISOString() : null, updated_at: new Date().toISOString() }).eq('id', feedback.id);
      if (error) throw error;
      setCurrentStatus(newStatus);
      toast({ title: "G├╝ncellendi", description: `Durum: ${getStatusLabel(newStatus)}` });
      if (onFeedbackUpdate) onFeedbackUpdate(feedback.id, { status: newStatus });
      else if (onStatusChange) onStatusChange(feedback.id, newStatus);
    } catch (e) { toast({ variant: "destructive", title: "Hata" }); } finally { setIsUpdating(false); }
  };

  const handleSaveNote = async () => {
    if (!user) return;
    setIsSavingNote(true);
    try {
      const now = new Date().toISOString();
      const { error } = await supabase.from('feedbacks').update({ manager_note: managerNote, manager_note_updated_by: user.id, manager_note_updated_at: now }).eq('id', feedback.id);
      if (error) throw error;
      toast({ title: "Not Kaydedildi", className: "bg-green-600 text-white border-none" });
      setLastUpdatedInfo(`Siz - ${new Date(now).toLocaleString('tr-TR')}`);
      if (onFeedbackUpdate) onFeedbackUpdate(feedback.id, { manager_note: managerNote });
      else if (onStatusChange) onStatusChange(feedback.id, currentStatus, managerNote);
    } catch (e) { toast({ variant: "destructive", title: "Hata" }); } finally { setIsSavingNote(false); }
  };

  const handleRemoveNote = async () => {
    if (!user) return;
    setIsSavingNote(true);
    try {
      const now = new Date().toISOString();
      const { error } = await supabase.from('feedbacks').update({ manager_note: null, manager_note_updated_by: user.id, manager_note_updated_at: now }).eq('id', feedback.id);
      if (error) throw error;
      setManagerNote('');
      toast({ title: "Not Silindi", className: "bg-red-600 text-white border-none" });
      setLastUpdatedInfo(`Siz - ${new Date(now).toLocaleString('tr-TR')}`);
      if (onFeedbackUpdate) onFeedbackUpdate(feedback.id, { manager_note: null });
      else if (onStatusChange) onStatusChange(feedback.id, currentStatus, null);
    } catch (e) { toast({ variant: "destructive", title: "Hata" }); } finally { setIsSavingNote(false); }
  };

  const handleNextImage = (e) => { e.stopPropagation(); setCurrentImageIndex((prev) => (prev + 1) % allImages.length); };
  const handlePrevImage = (e) => { e.stopPropagation(); setCurrentImageIndex((prev) => (prev - 1 + allImages.length) % allImages.length); };
  const handleOpenImage = (e) => { e.stopPropagation(); const url = allImages[currentImageIndex]; if (url) window.open(url, '_blank'); };

  const getStatusLabel = (s) => ({ new: 'Yeni', pending: 'Beklemede', in_progress: '─░┼şlemde', resolved: '├ç├Âz├╝ld├╝', escalated: 'Acil' }[s] || s);
  const getStatusColor = (s) => ({ new: 'bg-cyan-500/20 text-cyan-400 border-cyan-500/50', pending: 'bg-indigo-500/20 text-indigo-400 border-indigo-500/50', in_progress: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/50', resolved: 'bg-green-500/20 text-green-400 border-green-500/50', escalated: 'bg-red-500/20 text-red-500 border-red-500 font-bold' }[s] || 'bg-slate-700');
  const getTypeLabel = (t) => ({ complaint: '┼Şikayet', suggestion: '├ûneri', evaluation: 'De─şerlendirme', review: 'De─şerlendirme', rating: 'De─şerlendirme' }[t] || 'Geri Bildirim');
  const getHeaderIcon = () => { if (currentStatus === 'escalated') return <Siren className="w-6 h-6 text-white animate-spin-slow" />; return feedback.feedback_type === 'complaint' ? <AlertTriangle className="w-5 h-5 text-red-500" /> : <Star className="w-5 h-5 text-yellow-500" />; };

  if (!feedback) return null;

  return (
    <>
      <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
        <DialogContent className="text-slate-100 max-w-2xl max-h-[90vh] flex flex-col bg-slate-900 border-slate-800 p-0 gap-0 overflow-hidden">
          <DialogHeader className="px-6 pt-4 pb-2 border-b border-slate-800 flex-shrink-0">
            <div className="flex items-center justify-between gap-2">
              <DialogTitle className="text-xl font-bold flex items-center gap-2 min-w-0">
                <div className={`p-2 rounded-full flex-shrink-0 ${currentStatus === 'escalated' ? 'bg-red-600 shadow-lg animate-pulse' : 'bg-slate-800'}`}>{getHeaderIcon()}</div>
                <span className="text-white">
                  {currentStatus === 'escalated' ? 'AC─░L M├£DAHALE GEREKL─░' : `${getTypeLabel(feedback.feedback_type)} Detay─▒`}
                </span>
              </DialogTitle>
              <DialogDescription className="text-slate-400 text-sm sr-only">
                Geri bildirimin t├╝m detaylar─▒n─▒ buradan inceleyebilirsiniz.
              </DialogDescription>
              <div className="flex items-center gap-2 mt-1 flex-shrink-0 mr-10">
                {isVip && <div className="flex items-center gap-1 px-2 py-0.5 bg-purple-500/10 rounded text-[10px] text-purple-300 border border-purple-500/30 font-medium whitespace-nowrap"><Crown className="w-3 h-3" /><span>VIP</span></div>}
                {isSensitive && <div className="flex items-center gap-1 px-2 py-0.5 bg-orange-500/10 rounded text-[10px] text-orange-300 border border-orange-500/30 font-medium whitespace-nowrap"><AlertTriangle className="w-3 h-3" /><span>Hassas</span></div>}
                <Badge className={`${getStatusColor(currentStatus)} px-3 py-1 text-sm whitespace-nowrap`}>{getStatusLabel(currentStatus)}</Badge>
              </div>
            </div>
          </DialogHeader>

          <div className="space-y-6 mt-0 flex-1 overflow-y-auto overflow-x-hidden px-6 py-4 w-full">
            {managerNote && (<div onClick={() => notesSectionRef.current?.scrollIntoView({ behavior: 'smooth' })} className="bg-amber-900/20 border border-amber-500/30 rounded-lg p-3 flex items-center justify-between cursor-pointer hover:bg-amber-900/30 transition-colors group"><div className="flex items-center gap-2"><StickyNote className="w-4 h-4 text-amber-500" /><span className="text-sm text-amber-200 font-medium">Y├Ânetici notu var</span></div><span className="text-xs text-amber-400 underline">G├Âr├╝nt├╝le</span></div>)}

            <div className={`rounded-lg p-4 border relative overflow-hidden ${currentStatus === 'escalated' ? 'bg-red-900/10 border-red-500/30' : 'bg-slate-800/50 border-slate-700/50'}`}>
              <div className="flex flex-col md:flex-row justify-between items-start gap-4 mb-4">
                <div className="flex-1 min-w-0 overflow-hidden">
                  <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-2 flex items-center gap-2"><User className="w-4 h-4" /> M├╝┼şteri Bilgileri</h3>
                  <div className="flex flex-col gap-1 mb-2">
                    <div className="flex items-center gap-2">
                      <span className="font-bold text-lg text-white break-words" title={customerProfileNote ? "M├╝┼şteri Notu Mevcut" : ""}>{formattedName}</span>
                    </div>
                    {/* ­şşó SADECE KAYITLI ─░SE G├ûSTER */}
                    {customerJoinDate && !isAnonymous && (<div className="flex items-center gap-2 text-xs text-slate-400"><User className="w-3 h-3 text-slate-500" /><span>├£yelik: {new Date(customerJoinDate).toLocaleDateString('tr-TR')}</span></div>)}
                  </div>

                  {/* ­şşó ─░STAT─░ST─░KLER - SADECE KAYITLI ─░SE */}
                  {!isAnonymous ? (
                    customerStats ? (
                      <div className="text-xs text-slate-400 mt-2 flex flex-wrap gap-x-3 gap-y-1">
                        <span className="font-medium text-slate-300">Toplam: {customerStats.total}</span>
                        <span className="text-red-400">┼Şikayet: {customerStats.complaints}</span>
                        <span className="text-blue-400">├ûneri: {customerStats.suggestions}</span>
                        <span className="text-yellow-400">De─ş.: {customerStats.evaluations}</span>
                      </div>
                    ) : statsLoading ? (
                      <div className="text-xs text-slate-500 flex items-center gap-1 mt-1"><Loader2 className="w-3 h-3 animate-spin" /> Y├╝kleniyor...</div>
                    ) : (
                      <div className="text-xs text-slate-500 italic mt-1">Veri yok.</div>
                    )
                  ) : (
                    // ­şşó ANON─░M ─░├ç─░N BO┼Ş MESAJ
                    <div className="text-xs text-slate-500 italic mt-1">Anonim kullan─▒c─▒ (Profil verisi yok)</div>
                  )}

                  {/* ­şşó PROF─░L BUTONU - SADECE KAYITLI/PROF─░LL─░ ─░SE */}
                  {(liveProfileData || !isAnonymous) && (
                    <div className="mt-3">
                      <Button variant="outline" size="sm" onClick={() => setIsProfileModalOpen(true)} className="h-8 text-xs border-teal-500/40 text-teal-400 bg-teal-500/10 hover:bg-teal-500/20 w-full md:w-auto"><User className="w-3.5 h-3.5 mr-1.5" /> Profili G├Âr├╝nt├╝le</Button>
                    </div>
                  )}
                </div>

