  const [businessName, setBusinessName] = useState('');
  const [businessCreatedAt, setBusinessCreatedAt] = useState(null);

  const [isSpecialOffer, setIsSpecialOffer] = useState(false);
  const [monthlyFeeOverride, setMonthlyFeeOverride] = useState(null);

  // ­şşó YEN─░: Role-based access control
  const [userRole, setUserRole] = useState(null); // 'owner' | 'branch_manager'
  const [assignedBranchId, setAssignedBranchId] = useState(null);

  const [branches, setBranches] = useState([]);
  const [selectedBranchId, setSelectedBranchId] = useState('all');

  const [dateRange, setDateRange] = useState('last7');

  const [qrCount, setQrCount] = useState(0);
  const [loading, setLoading] = useState(true);

  // ­şşó B─░LD─░R─░M STATE (Centralized)
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [escalatedCount, setEscalatedCount] = useState(0);

  // Date Range Helper
  const getDateRange = useCallback((range) => {
    const endDate = new Date();
    let startDate = new Date();

    endDate.setHours(23, 59, 59, 999);
    startDate.setHours(0, 0, 0, 0);

    switch (range) {
      case 'today':
        break;
      case 'last7':
        startDate.setDate(endDate.getDate() - 7);
        break;
      case 'last30':
        startDate.setDate(endDate.getDate() - 30);
        break;
      case 'last90':
        startDate.setDate(endDate.getDate() - 90);
        break;
      case 'thisMonth':
        startDate = new Date(endDate.getFullYear(), endDate.getMonth(), 1);
        break;
      case 'allTime':
        startDate = businessCreatedAt ? new Date(businessCreatedAt) : new Date(2020, 0, 1);
        break;
      default:
        startDate.setDate(endDate.getDate() - 7);
        break;
    }

    return { startDate, endDate };
  }, [businessCreatedAt]);

  const getDateFilterISO = useCallback((range) => {
    if (range === 'allTime') {
      return null;
    }
    const { startDate } = getDateRange(range);
    return startDate ? startDate.toISOString() : null;
  }, [getDateRange]);

  // ­şşó UPDATED: Main Data Fetcher with Role-Based Access Control
  const refreshData = useCallback(async () => {
    if (!user) return;

    setLoading(true);
    try {
      // 1. Fetch Manager & Business + Role Info
      const { data: profileData, error: profileError } = await supabase
        .from('manager_profiles')
        .select(`
          business_id, 
          role, 
          assigned_branch_id,
          businesses(business_name, created_at, is_special_offer, monthly_fee_override)
        `)
        .eq('user_id', user.id)
        .maybeSingle();

      if (profileError) throw profileError;
      if (!profileData) {
        setLoading(false);
        return;
      }

      const bId = profileData.business_id;
      const role = profileData.role || 'owner'; // Default to owner for backwards compatibility
      const assignedBranch = profileData.assigned_branch_id;

      setBusinessId(bId);
      setBusinessName(profileData.businesses?.business_name || '─░┼şletmem');
      setBusinessCreatedAt(profileData.businesses?.created_at);
      setIsSpecialOffer(profileData.businesses?.is_special_offer || false);
      setMonthlyFeeOverride(profileData.businesses?.monthly_fee_override);
      setUserRole(role);
      setAssignedBranchId(assignedBranch);

      // 2. Fetch Branches (with role-based filtering)
      let branchQuery = supabase
        .from('branches')
        .select('id, branch_name_tr')
        .eq('business_id', bId)
        .eq('is_active', true)
        .order('branch_name_tr');

      // ­şşó If branch_manager, only fetch assigned branch
      if (role === 'branch_manager' && assignedBranch) {
        branchQuery = branchQuery.eq('id', assignedBranch);
      }

      const { data: branchData, error: branchError } = await branchQuery;

      if (branchError) throw branchError;
      setBranches(branchData || []);

      // ­şşó Force branch_manager to their assigned branch
      if (role === 'branch_manager' && assignedBranch) {
        setSelectedBranchId(assignedBranch);
      } else if (role === 'owner') {
        // Owner can keep 'all' or their previous selection
        // Only reset if current selection is invalid
        const validBranchIds = (branchData || []).map(b => b.id);
        if (selectedBranchId !== 'all' && !validBranchIds.includes(selectedBranchId)) {
          setSelectedBranchId('all');
        }
      }

      // 3. Fetch QR Count
      const { startDate, endDate } = getDateRange(dateRange);

      let qrQuery = supabase
        .from('qr_scans')
        .select('*', { count: 'exact', head: true })
        .eq('business_id', bId)
        .gte('created_at', startDate.toISOString())
        .lte('created_at', endDate.toISOString());

      // ­şşó Apply branch filter based on role
      if (role === 'branch_manager' && assignedBranch) {
        qrQuery = qrQuery.eq('branch_id', assignedBranch);
      } else if (selectedBranchId && selectedBranchId !== 'all') {
        qrQuery = qrQuery.eq('branch_id', selectedBranchId);
      }

      const { count, error: qrError } = await qrQuery;

      if (qrError) {
        console.error('Ôøö QR Query Error:', qrError);
        throw qrError;
      }

      setQrCount(count || 0);

    } catch (error) {
      console.error('Ôøö AdminContext Load Error:', error);
      toast({
        variant: "destructive",
        title: "Veri Y├╝kleme Hatas─▒",
        description: error.message || "Y├Ânetici bilgileri al─▒namad─▒."
      });
    } finally {
      setLoading(false);
    }
  }, [user, toast, selectedBranchId, dateRange, getDateRange]);

  // ­şşó FETCH NOTIFICATIONS (Centralized)
  const fetchNotifications = useCallback(async () => {
    if (!user || !businessId) return;
    let query = supabase.from('notifications').select('*, feedbacks(feedback_type)').eq('user_id', user.id).eq('business_id', businessId);
    if (userRole === 'branch_manager' && assignedBranchId) query = query.eq('branch_id', assignedBranchId);

    const { data } = await query.order('created_at', { ascending: false }).limit(20);
    setNotifications(data || []);
    setUnreadCount((data || []).filter(n => !n.is_read).length);
  }, [user, businessId, userRole, assignedBranchId]);

  // ­şşó CHECK ESCALATED STATUS (Centralized)
  const checkEscalatedStatus = useCallback(async () => {
    if (!businessId) return;
    try {
      let query = supabase.from('feedbacks')
        .select('*', { count: 'exact', head: true })
        .eq('business_id', businessId)
        .eq('status', 'escalated');

      if (userRole === 'branch_manager' && assignedBranchId) {
        query = query.eq('branch_id', assignedBranchId);
      }
      const { count } = await query;
      setEscalatedCount(count || 0);
    } catch (e) {
      console.error(e);
    }
  }, [businessId, userRole, assignedBranchId]);

  // ­şşó MARK AS READ HELPERS
  const markNotificationAsRead = useCallback(async (notificationId) => {
    setNotifications(prev => prev.map(n => n.id === notificationId ? { ...n, is_read: true } : n));
    setUnreadCount(prev => Math.max(0, prev - 1));
    await supabase.from('notifications').update({ is_read: true }).eq('id', notificationId);
  }, []);

  const markAllNotificationsAsRead = useCallback(async () => {
    setNotifications(prev => prev.map(n => ({ ...n, is_read: true })));
    setUnreadCount(0);
    await supabase.from('notifications').update({ is_read: true }).eq('user_id', user.id).eq('is_read', false);
    toast({ title: 'T├╝m bildirimler okundu.' });
  }, [user, toast]);

  // ­şşó FIX: Split effects to prevent deadlock
  // 1. Initial Data Fetch (Business, Branch, Role)
  useEffect(() => {
    if (user) {
      refreshData();
    } else {
      setLoading(false);
      setBusinessId(null);
      setBranches([]);
      setUserRole(null);
      setAssignedBranchId(null);
    }
  }, [user, refreshData]);

  // 2. Dependent Data Fetch (Notifications, Escalated) - Runs after businessId is set
  useEffect(() => {
    if (user && businessId) {
      fetchNotifications();
      checkEscalatedStatus();
    } else if (!user) {
      setNotifications([]);
      setUnreadCount(0);
      setEscalatedCount(0);
    }
  }, [user, businessId, fetchNotifications, checkEscalatedStatus]);

  // Realtime QR Subscription
  // Realtime QR & Notifications Subscription
  const subscriptionDebounceRef = React.useRef(null);

  useEffect(() => {
    if (!businessId || !user) return;

    // 1. QR Channel
    const qrChannel = supabase
      .channel('admin-qr-updates')
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'qr_scans', filter: `business_id=eq.${businessId}` },
        () => {
          refreshData(); // Refresh stats
          toast({
            title: "Yeni QR Tarama!",
            description: "Bir m├╝┼şteri QR kodunuzu tarad─▒.",
          });
        }
      )
      .subscribe();

    // 2. Notifications Channel
    const notifChannel = supabase.channel('admin-global-notifications')
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'notifications', filter: `user_id=eq.${user.id}` }, (payload) => {
        const newNotification = payload.new;
        const isRelevant = userRole === 'branch_manager' ? newNotification.branch_id === assignedBranchId : newNotification.business_id === businessId;

        if (isRelevant) {
          setNotifications(prev => [newNotification, ...prev]);
          setUnreadCount(prev => prev + 1);
          toast({ title: `Yeni Bildirim`, description: newNotification.message || 'Yeni bildirim.' });
        }
      })
      .subscribe();

    // 3. Feedback Updates Channel (for Escalated Count & Stats)
    const feedbackChannel = supabase.channel('admin-feedback-updates')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'feedbacks', filter: `business_id=eq.${businessId}` }, () => {
        // Debounce to prevent flooding
        if (subscriptionDebounceRef.current) clearTimeout(subscriptionDebounceRef.current);
        subscriptionDebounceRef.current = setTimeout(() => {
          checkEscalatedStatus();
          refreshData(); // Refresh charts/stats too if feedback changes
        }, 1500);
      }).subscribe();

    return () => {
      supabase.removeChannel(qrChannel);
      supabase.removeChannel(notifChannel);
      supabase.removeChannel(feedbackChannel);
      if (subscriptionDebounceRef.current) clearTimeout(subscriptionDebounceRef.current);
    };
  }, [businessId, user, toast, refreshData, userRole, assignedBranchId, checkEscalatedStatus]);

  // ­şşó Override setSelectedBranchId to prevent branch_manager from changing branches
  const handleSetSelectedBranchId = useCallback((newBranchId) => {
    if (userRole === 'branch_manager' && assignedBranchId) {
      // Branch managers cannot change branches
      console.warn('Branch managers cannot change branch selection');
      return;
    }
    setSelectedBranchId(newBranchId);
  }, [userRole, assignedBranchId]);

  return (
    <AdminContext.Provider value={{
      businessId,
      businessName,
      businessCreatedAt,
      branches,
      selectedBranchId,
      setSelectedBranchId: handleSetSelectedBranchId, // ­şşó Protected setter
      dateRange,
      setDateRange,
      getDateRange,
      getDateFilterISO,
      qrCount,
      loading,
      refreshData,
      isSpecialOffer,
      monthlyFeeOverride,
      userRole, // ­şşó NEW
      assignedBranchId, // ­şşó NEW
      isOwner: userRole === 'owner',
      isBranchManager: userRole === 'branch_manager',
      // ­şşó Export Notification Data
      notifications,
      unreadCount,
      escalatedCount,
      markNotificationAsRead,
      markAllNotificationsAsRead,
      checkEscalatedStatus
    }}>
      {children}
    </AdminContext.Provider>
  );
};

export const useAdminContext = () => {
  const context = useContext(AdminContext);
  if (context === undefined) {
    throw new Error('useAdminContext must be used within an AdminProvider');
  }
  return context;
};

import React, { createContext, useContext, useEffect, useState, useCallback, useMemo, useRef } from 'react';
import { supabase } from '@/lib/customSupabaseClient';
import { useToast } from '@/components/ui/use-toast';
import { clearVocalizeCache } from '@/lib/cacheUtils'; // Ô£à YEN─░ SATIR

const AuthContext = createContext(undefined);

export const AuthProvider = ({ children }) => {
  const { toast } = useToast();

  const [user, setUser] = useState(null);
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isGuest, setIsGuest] = useState(false);

  // Flag to prevent onAuthStateChange from overriding manual loading state during sign out
  const isSigningOut = useRef(false);

  const handleSession = useCallback((session) => {
    setSession(session);
    setUser(session?.user ?? null);
    if (session?.user) {
      setIsGuest(false);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    let mounted = true;

    const getSession = async () => {
      try {
        const { data: { session }, error } = await supabase.auth.getSession();
        if (error) throw error;
        if (mounted) handleSession(session);
      } catch (error) {
        console.error("Auth session fetch error:", error);
        if (mounted) setLoading(false);
      }
    };

    getSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      (event, session) => {
        // Don't process auth changes if we are manually handling sign out
        if (mounted && !isSigningOut.current) handleSession(session);
      }
    );

    return () => {
      mounted = false;
      subscription.unsubscribe();
    };
  }, [handleSession]);

  const signUp = useCallback(async (email, password, options) => {
    try {
      const { error } = await supabase.auth.signUp({
        email,
        password,
        options,
      });

      if (error) {
        toast({
          variant: "destructive",
          title: "Sign up Failed",
          description: error.message || "Something went wrong",
        });
      }
      return { error };
    } catch (err) {
      console.error("Sign up error:", err);
      return { error: err };
    }
  }, [toast]);

  const signIn = useCallback(async (email, password) => {
    try {
      const { error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) {
        toast({
          variant: "destructive",
          title: "Sign in Failed",
          description: error.message || "Something went wrong",
        });
      }
      return { error };
    } catch (err) {
      console.error("Sign in error:", err);
      return { error: err };
    }
  }, [toast]);

  const signOut = useCallback(async () => {
    try {
      isSigningOut.current = true;
      setLoading(true); // Start loading UI

      // Ô£à YEN─░: Cache temizle (logout ├Âncesi)
      clearVocalizeCache();

      // KR─░T─░K D├£ZELTME: scope: 'local' parametresi eklendi
      // Bu "auth session missing" hatas─▒n─▒ ├Ânler
      const { error } = await supabase.auth.signOut({ scope: 'local' });

      // Reset all states
      setIsGuest(false);
      setUser(null);
      setSession(null);

      // Force a small delay to let the loading screen be seen and ensuring smooth transition
      await new Promise(resolve => setTimeout(resolve, 1500));

      if (error) {
        // Session missing hatas─▒ ├Ânemli de─şil, yine de ├ğ─▒k─▒┼ş yapt─▒r
        if (error.message?.includes('session')) {
          console.warn('Session already cleared:', error);
          isSigningOut.current = false;
          setLoading(false);
          return { error: null };
        }

        toast({
          variant: "destructive",
          title: "├ç─▒k─▒┼ş Hatas─▒",
          description: error.message || "Bir sorun olu┼ştu",
        });
        isSigningOut.current = false;
        setLoading(false);
        return { error };
      }

      isSigningOut.current = false;
      setLoading(false);
      return { error: null };
    } catch (err) {
      console.error("Sign out error:", err);
      // Hata olsa bile state'i temizle
      setIsGuest(false);
      setUser(null);
      setSession(null);
      isSigningOut.current = false;
      setLoading(false);
      return { error: err };
    }
  }, [toast]);

  const loginAsGuest = useCallback(async () => {
    // ­şşó KR─░T─░K D├£ZELTME: E─şer aktif bir kullan─▒c─▒ oturumu varsa, misafir giri┼şinden ├Ânce onu temizle.
    // Bu, misafir panelinde eski kullan─▒c─▒ verilerinin g├Âr├╝nmesini engeller.
    if (user || session) {
      isSigningOut.current = true;
      try {
        await supabase.auth.signOut({ scope: 'local' });
        // State'leri hemen temizle
        setUser(null);
        setSession(null);
      } catch (err) {
        console.error("Session clear error during guest login:", err);
      } finally {
        isSigningOut.current = false;
      }
    }

    setIsGuest(true);
    localStorage.setItem('vocalize_guest_mode', 'true'); // Persistent guest mode
  }, [user, session]);

  const value = useMemo(() => ({
    user,
    session,
    loading,
    isGuest,
    signUp,
    signIn,
    signOut,
    loginAsGuest,
  }), [user, session, loading, isGuest, signUp, signIn, signOut, loginAsGuest]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import { supabase } from '@/lib/customSupabaseClient';
import { findErrorByMessage } from '@/constants/errorCodes';

// Error deduplication cache (in-memory)
const errorCache = new Map();
const DEDUP_WINDOW_MS = 5 * 60 * 1000; // 5 minutes

// generateErrorHash removed - using inline simple hashing

/**
 * Check if error was recently logged (deduplication) using LocalStorage for persistence
 */
const isRecentlyLogged = (errorHash) => {
    try {
        // Use sessionStorage for per-session throttling
        // If user closes tab/browser, session clears -> new error can be reported
        const cached = sessionStorage.getItem(`err_log_${errorHash}`);
        if (!cached) return false;

        return true; // If it exists in session, it's already logged this session
    } catch (e) {
        return errorCache.get(errorHash) && (Date.now() - errorCache.get(errorHash) < DEDUP_WINDOW_MS);
    }
};

/**
 * Mark error as logged in LocalStorage
 */
const markAsLogged = (errorHash) => {
    const now = Date.now();
    try {
        sessionStorage.setItem(`err_log_${errorHash}`, now.toString());
    } catch (e) {
        errorCache.set(errorHash, now);
    }
};

/**
 * Log error to Supabase client_errors table
 */
const logToSupabase = async (errorData) => {
    try {
        const { error } = await supabase.from('client_errors').insert(errorData);

        if (error) {
            console.error('Failed to log error to Supabase:', error);
            return false;
        }

        return true;
    } catch (err) {
        console.error('Error logging to Supabase:', err);
        return false;
    }
};

/**
 * Send email notification for critical errors via Supabase Edge Function
 */
const sendEmailNotification = async (errorData) => {
    try {
        const { data, error } = await supabase.functions.invoke('send-error-email', {
            body: {
                errorCode: errorData.error_code,
                message: errorData.message,
                stack: errorData.stack,
                url: errorData.url,
                userAgent: errorData.user_agent,
                userId: errorData.user_id,
                timestamp: errorData.created_at,
                to: 'support@vocalize.global'
            }
        });

        if (error) {
            console.error('Failed to send error email:', error);
            return false;
        }

        return true;
    } catch (err) {
        console.error('Error sending email notification:', err);
        return false;
    }
};

/**
 * Main error logging function
 * 
 * @param {Error} error - The error object
 * @param {Object} context - Additional context (component, action, etc.)
 * @returns {Object} - { errorCode, severity, shouldNotifyUser }
 */
export const logError = async (error, context = {}) => {
    try {
        // Safe error message extraction
        const errorMessage = error?.message || 'Unknown error';
        const errorStack = error?.stack || '';

        // Generate error hash for deduplication
        // Use simple string concat instead of btoa to avoid encoding issues with Turkish chars
        const errorHash = `HASH_${errorMessage}_${errorStack.substring(0, 100)}_${context?.component || ''}`;

        // Check if this error was recently logged
        if (isRecentlyLogged(errorHash)) {
            console.warn(`[ErrorLogger] Duplicate error suppressed: ${errorMessage.substring(0, 50)}...`);
            // Return existing error info if known, or generic
            const errorInfo = findErrorByMessage(errorMessage);
            return {
                errorCode: errorInfo.code,
                severity: errorInfo.severity,
                shouldNotifyUser: false,
                isDuplicate: true
            };
        }

        // OPTIMISTIC DEDUPLICATION: Mark as logged BEFORE async work
        // This prevents race conditions where multiple identical errors fire rapidly
        markAsLogged(errorHash);

        // Find matching error code
        const errorInfo = findErrorByMessage(errorMessage);
        const { code: errorCode, severity } = errorInfo;

        // Get current session (safely)
        let session = null;
        try {
            const { data } = await supabase.auth.getSession();
            session = data?.session;
        } catch (authErr) {
            console.warn("[ErrorLogger] Failed to get session:", authErr);
        }

        // Prepare error data
        const errorData = {
            error_code: errorCode,
            severity: severity,
            message: errorMessage,
            stack: errorStack,
            component: context.component || null,
            action: context.action || null,
            url: window.location.href,
            user_agent: navigator.userAgent,
            user_id: session?.user?.id || null,
            user_email: session?.user?.email || null,
            additional_data: context.additionalData ? JSON.stringify(context.additionalData) : null,
            created_at: new Date().toISOString()
        };

        // Log to Supabase (Non-blocking / Background)
        logToSupabase(errorData).then(logged => {
            if (logged && severity === 'CRITICAL') {
                sendEmailNotification(errorData).catch(err => {
                    console.error('Email notification failed:', err);
                });
            }
        });

        // Determine if user should be notified
        const shouldNotifyUser = severity === 'CRITICAL' || severity === 'RECOVERABLE';

        return {
            errorCode,
            severity,
            shouldNotifyUser,
            isDuplicate: false,
            logged: true // Optimistic
        };

    } catch (err) {
        // Failsafe: If logger itself crashes, just print to console and return generic critical error
        // Do NOT try to recursive log
        console.error('[ErrorLogger] CRITICAL LOGGER FAILURE:', err);
        return {
            errorCode: 'ERR_INTERNAL',
            severity: 'CRITICAL',
            shouldNotifyUser: true,
            isDuplicate: false,
            logged: false
        };
    }
};

/**
 * Log warning (non-error issues)
 */
export const logWarning = (message, context = {}) => {
    console.warn(`[Warning] ${message}`, context);

    // Optionally log warnings to Supabase as well
    // For now, just console.warn
};

/**
 * Clear error cache (useful for testing)
 */
export const clearErrorCache = () => {
    errorCache.clear();
};

