  // --- INITIALIZATION ---
  useEffect(() => {
    const init = async () => {
      if (authLoading) return;
      setIsLoading(true);
      try {
        const guestMode = localStorage.getItem('vocalize_guest_mode');
        let isGuestUser = guestParam === 'true' || guestMode === 'true';

        if (authUser) {
          isGuestUser = false;
          if (guestMode) localStorage.removeItem('vocalize_guest_mode');
        }

        setIsGuest(isGuestUser);

        if (authUser && !isGuestUser) {
          setUser(authUser);
          setSupportEmail(authUser.email || '');

          const { data: profile } = await supabase
            .from('customer_profiles')
            .select('*')
            .eq('user_id', authUser.id)
            .maybeSingle();

          const metaName = authUser.user_metadata?.full_name ||
            (authUser.user_metadata?.first_name ? `${authUser.user_metadata.first_name} ${authUser.user_metadata.last_name}` : '');

          setUserProfile({
            name: profile?.name || metaName || 'Kullan─▒c─▒',
            email: authUser.email,
            phone: profile?.phone || authUser.user_metadata?.phone
          });
        } else if (isGuestUser) {
          setUser(null);
          setSupportEmail('');
        }

        // ­şşó YEN─░: URL parametreleri PRIMARY, localStorage FALLBACK
        let targetBusinessId = businessParam; // URL parametresi VARSA KULLAN
        let targetBranchId = branchParam;

        // E─şer URL'de yoksa localStorage'dan oku (fallback)
        if (!targetBusinessId) {
          const lastBusiness = localStorage.getItem('vocalize_last_business');
          if (lastBusiness) {
            targetBusinessId = lastBusiness;
            console.log('[CustomerPanel] localStorage fallback - i┼şletme:', targetBusinessId);
          }
        }

        if (!targetBranchId && targetBusinessId) {
          const lastBranch = localStorage.getItem('vocalize_last_branch');
          if (lastBranch) {
            targetBranchId = lastBranch;
            console.log('[CustomerPanel] localStorage fallback - ┼şube:', targetBranchId);
          }
        }

        if (qrParam) {
          setHasScannedQR(true);
          if (branchParam) {
            const { data: branchData } = await supabase.from('branches').select('branch_name_tr').eq('id', branchParam).single();
            if (branchData) {
              setQrInfo({ business_id: businessParam, branch_id: branchParam, qr_code: qrParam, branch_name: branchData.branch_name_tr });
            }
          }
        }

        if (targetBusinessId) {
          setSelectedBusiness(targetBusinessId);
          await fetchBranches(targetBusinessId);

          const newParams = new URLSearchParams(searchParams);
          newParams.set('business', targetBusinessId);

          if (targetBranchId) {
            setSelectedBranch(targetBranchId);
            newParams.set('branch', targetBranchId);
          }

          if (language) newParams.set('lang', language);
          if (isGuestUser) newParams.set('guest', 'true');

          if (location.search !== `?${newParams.toString()}`) {
            navigate(`${location.pathname}?${newParams.toString()}`, { replace: true });
          }
        }

        await fetchBusinesses();
      } catch (error) {
        console.error('Initialization error:', error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [businessParam, branchParam, qrParam, guestParam, authUser, authLoading]);

  const fetchBusinesses = useCallback(async () => {
    try {
      let allBusinessIds = [];
      const visitedBusinessesJson = localStorage.getItem('vocalize_visited_businesses');
      const localIds = visitedBusinessesJson ? JSON.parse(visitedBusinessesJson) : [];
      allBusinessIds = [...localIds];

      if (authUser?.email && !isGuest) {
        const { data: dbBusinesses, error } = await supabase
          .from('customer_visited_businesses')
          .select('business_id')
          .eq('customer_email', authUser.email);

        if (!error && dbBusinesses) {
          const dbIds = dbBusinesses.map(b => b.business_id);
          allBusinessIds = [...new Set([...allBusinessIds, ...dbIds])];
          localStorage.setItem('vocalize_visited_businesses', JSON.stringify(allBusinessIds));
        }
      }

      if (allBusinessIds.length === 0) {
        setBusinesses([]);
        return;
      }

      const { data, error } = await supabase
        .from('businesses')
        .select('id, business_name')
        .in('id', allBusinessIds);

      if (error) throw error;
      setBusinesses(data || []);
    } catch (error) {
      console.error('Error fetching businesses:', error);
      setBusinesses([]);
    }
  }, [authUser, isGuest]);

  const fetchBranches = useCallback(async (businessId) => {
    if (!businessId) return;
    try {
      const { data, error } = await supabase
        .from('branches')
        .select('*')
        .eq('business_id', businessId)
        .eq('is_active', true);

      if (error) throw error;
      setBranches(data || []);
    } catch (error) {
      console.error('Error fetching branches:', error);
    }
  }, []);

