                        <th className="px-6 py-4 text-center border-r border-slate-800/50 bg-slate-900/50 text-sky-400 cursor-help">
                          <div className="flex items-center justify-center gap-1">­şÅå Lig Puan─▒ <InfoTooltip text="Kalite, Operasyon ve Veri Pay─▒ puanlar─▒n─▒n a─ş─▒rl─▒kl─▒ ortalamas─▒." /></div>
                        </th>
                        <th className="px-6 py-4 text-center border-r border-slate-800/50 cursor-help">
                          <div className="flex items-center justify-center gap-1">Ô¡É Kalite <InfoTooltip text="Y─▒ld─▒z puan ortalamas─▒." /></div>
