                                : "text-slate-400 hover:text-white hover:bg-slate-800"
                            )}
                          >
                            {page}
                          </Button>
                        </React.Fragment>
                      );
                    })}
                </div>

                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    const totalPages = Math.ceil(totalServerCount / itemsPerPage);
                    const newPage = Math.min(totalPages, currentPage + 1);
                    setCurrentPage(newPage);
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                  }}
                  disabled={currentPage === Math.ceil(totalServerCount / itemsPerPage) || loading}
                  className="border-teal-500/30 text-teal-500 hover:bg-teal-500/10 disabled:opacity-30 h-9 w-9 p-0"
                >
                  <ChevronRight className="w-4 h-4" />
                </Button>
              </div>

              <div className="text-center text-xs text-slate-500">
                Toplam <span className="text-teal-500 font-medium">{totalServerCount}</span> kay─▒ttan <span className="text-slate-300">{(currentPage - 1) * itemsPerPage + 1} - {Math.min(currentPage * itemsPerPage, totalServerCount)}</span> aras─▒ g├Âsteriliyor
              </div>
            </div>
          )}
        </div>

        {/* MODALLAR EN DI┼ŞTA */}
        {selectedFeedback && (
          <FeedbackDetailModal
            isOpen={isDetailModalOpen}
            onClose={() => setIsDetailModalOpen(false)}
            feedback={selectedFeedback}
            onFeedbackUpdate={(id, u) => setFeedbacks(p => p.map(f => f.id === id ? { ...f, ...u } : f))}
            onFlagsUpdate={handleFlagsUpdate}
          />
        )}

        {customerModalOpen && (
          <CustomerProfileModal
            isOpen={customerModalOpen}
            onClose={() => setCustomerModalOpen(false)}
            customerProfileId={selectedCustomer?.id}
            customerEmail={selectedCustomer?.email}
            businessId={businessId}
            onFlagsUpdate={handleFlagsUpdate}
          />
        )}
      </div>
    </>
  );
};

