export default LandingPage;

import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/lib/customSupabaseClient';
import { useAuth } from '@/contexts/SupabaseAuthContext';
import { useToast } from '@/components/ui/use-toast';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { MessageSquare, Trash2, Check, Eye, EyeOff, Loader2, ServerCrash, Inbox, ChevronLeft, ChevronRight } from 'lucide-react';
import AdminMobileNavbar from '@/components/AdminMobileNavbar';
import FeedbackDetailModal from '@/components/FeedbackDetailModal';

const formatTimeAgo = (dateString) => {
    if (!dateString) return '';
    const date = new Date(dateString);
    const now = new Date();
    const seconds = Math.floor((now - date) / 1000);
    if (seconds < 60) return "az ├Ânce";
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes} dk ├Ânce`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours} sa ├Ânce`;
    const days = Math.floor(hours / 24);
    return `${days} g├╝n ├Ânce`;
};

const NotificationHistory = () => {
    const { user } = useAuth();
    const { toast } = useToast();
    const [notifications, setNotifications] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [selected, setSelected] = useState([]);
    const [filter, setFilter] = useState('all'); // 'all', 'read', 'unread'
    const [page, setPage] = useState(1);
    const [itemsPerPage] = useState(20);
    const [totalCount, setTotalCount] = useState(0);
    const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
    
    // Feedback Detail State
    const [selectedFeedback, setSelectedFeedback] = useState(null);
    const [isLoadingFeedback, setIsLoadingFeedback] = useState(false);

    const totalPages = Math.ceil(totalCount / itemsPerPage);

    const fetchNotifications = useCallback(async () => {
        if (!user) return;
        setLoading(true);
        setError(null);
        try {
            const from = (page - 1) * itemsPerPage;
            const to = from + itemsPerPage - 1;

            let query = supabase
                .from('notifications')
                .select('*, feedbacks(feedback_type)', { count: 'exact' })
                .eq('user_id', user.id);

            if (filter === 'read') query = query.eq('is_read', true);
            if (filter === 'unread') query = query.eq('is_read', false);

            query = query.order('created_at', { ascending: false }).range(from, to);

            let res = await query;
            if (res.error) {
                // Join hatas─▒ olabilir (├Ârn. feedback_id/related_id FK farkl─▒ysa); join olmadan dene
                let fallback = supabase.from('notifications').select('*', { count: 'exact' }).eq('user_id', user.id);
                if (filter === 'read') fallback = fallback.eq('is_read', true);
                if (filter === 'unread') fallback = fallback.eq('is_read', false);
                fallback = fallback.order('created_at', { ascending: false }).range(from, to);
                res = await fallback;
            }
            if (res.error) throw res.error;

            setNotifications(res.data || []);
            setTotalCount(res.count ?? 0);

        } catch (e) {
            console.error("Error fetching notification history:", e);
            setError("Bildirimler y├╝klenirken bir hata olu┼ştu.");
            toast({ variant: 'destructive', title: 'Hata', description: 'Bildirim ge├ğmi┼şi al─▒namad─▒.' });
        } finally {
            setLoading(false);
            setSelected([]);
        }
    }, [user, toast, filter, page, itemsPerPage]);

    const getNotificationLabel = (n) => {
        const type = n.feedbacks?.feedback_type || n.feedback_type;
        if (type === 'complaint') return 'Yeni bir ┼şikayetiniz var';
        if (type === 'suggestion') return 'Yeni bir ├Âneriniz var';
        if (type === 'evaluation' || type === 'review' || type === 'rating') return 'Yeni bir de─şerlendirmeniz var';
        return n.message || 'Yeni bildirim';
    };

    useEffect(() => {
        fetchNotifications();
    }, [fetchNotifications]);
    
    const handleBulkUpdate = async (updateData) => {
        try {
            const { error } = await supabase.from('notifications').update(updateData).in('id', selected);
            if (error) throw error;
            toast({ title: "Ba┼şar─▒l─▒!", description: `${selected.length} bildirim g├╝ncellendi.` });
            await fetchNotifications();
        } catch (error) { toast({ variant: "destructive", title: "Hata", description: "Toplu g├╝ncelleme ba┼şar─▒s─▒z." }); }
    };

    const handleBulkDelete = async () => {
        try {
            const { error } = await supabase.from('notifications').delete().in('id', selected);
            if (error) throw error;
            toast({ title: "Ba┼şar─▒l─▒!", description: `${selected.length} bildirim silindi.` });
            await fetchNotifications();
        } catch (error) { toast({ variant: "destructive", title: "Hata", description: "Toplu silme ba┼şar─▒s─▒z." }); }
        setIsDeleteModalOpen(false);
    };
    
    const handleNotificationClick = async (notification) => {
        const feedbackId = notification.related_id || notification.feedback_id;
        if (!feedbackId) return;
        
        // Mark as read immediately if unread
        if (!notification.is_read) {
            try {
                await supabase.from('notifications').update({ is_read: true }).eq('id', notification.id);
                // Optimistically update local state
                setNotifications(prev => prev.map(n => n.id === notification.id ? { ...n, is_read: true } : n));
            } catch (err) {
                console.error("Error marking notification read:", err);
            }
        }

        // Fetch feedback details
        setIsLoadingFeedback(true);
        try {
            const { data, error } = await supabase
                .from('feedbacks')
                .select(`
                  *,
                  feedback_images,
                  image_urls,
                  receipt_images,
                  receipt_url,
                  product_image_url,
                  branches (id, branch_name_tr),
                  customer_profiles (
                    id,
                    name,
                    email,
                    phone,
                    flag_vip_customer,
                    flag_sensitive_customer,
                    admin_note,
                    users (
                      first_name,
                      last_name
                    )
                  ),
                  manager_note_updater:manager_note_updated_by (
                    first_name,
                    last_name
                  )
                `)
                .eq('id', feedbackId)
                .single();
            
            if (error) throw error;
            setSelectedFeedback(data);
        } catch (err) {
            console.error("Error fetching feedback details:", err);
            toast({ variant: "destructive", title: "Hata", description: "Geri bildirim detaylar─▒ y├╝klenemedi." });
        } finally {
            setIsLoadingFeedback(false);
        }
    };

    const handleSelectAll = (checked) => setSelected(checked ? notifications.map(n => n.id) : []);

    const isAllSelected = selected.length > 0 && selected.length === notifications.length;

    return (
        <div className="mx-auto max-w-7xl pb-10 px-4 pt-20 md:px-6 md:pt-0 lg:px-8 relative">
            <AdminMobileNavbar />
            
            {isLoadingFeedback && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center backdrop-blur-sm">
                    <div className="bg-slate-900 p-6 rounded-lg border border-slate-700 flex flex-col items-center gap-3">
                        <Loader2 className="w-8 h-8 text-indigo-500 animate-spin" />
                        <span className="text-slate-300 font-medium">Detaylar y├╝kleniyor...</span>
                    </div>
                </div>
            )}

            <header className="mb-6 mt-4 md:mt-0 flex flex-col md:flex-row justify-between items-start gap-3">
                <div>
                    <h1 className="text-white font-bold text-3xl">Bildirim Ge├ğmi┼şi</h1>
                    <p className="text-slate-400 text-sm">T├╝m geri bildirim uyar─▒lar─▒n─▒z─▒ buradan y├Ânetin.</p>
                </div>
                <div className="flex items-center gap-2">
                    <Button variant={filter === 'all' ? 'default' : 'outline'} onClick={() => { setFilter('all'); setPage(1); }} size="sm" className="bg-slate-700 hover:bg-slate-600 border-slate-600">T├╝m├╝</Button>
                    <Button variant={filter === 'unread' ? 'default' : 'outline'} onClick={() => { setFilter('unread'); setPage(1); }} size="sm" className="bg-slate-700 hover:bg-slate-600 border-slate-600">Okunmam─▒┼ş</Button>
                    <Button variant={filter === 'read' ? 'default' : 'outline'} onClick={() => { setFilter('read'); setPage(1); }} size="sm" className="bg-slate-700 hover:bg-slate-600 border-slate-600">Okunmu┼ş</Button>
                </div>
            </header>

            {selected.length > 0 && (
                <div className="bg-blue-900/20 border border-blue-500/30 rounded-lg p-3 md:p-4 mb-4 flex flex-col md:flex-row items-center justify-between gap-4">
                    <div><span className="text-blue-400 font-medium">{selected.length} bildirim se├ğildi</span><Button variant="link" className="text-blue-400 hover:text-blue-300 text-sm" onClick={() => setSelected([])}>Se├ğimi Kald─▒r</Button></div>
                    <div className="flex items-center gap-2">
                        <Button size="sm" onClick={() => handleBulkUpdate({ is_read: true })} className="bg-blue-600 hover:bg-blue-700"><Eye className="w-4 h-4 mr-2"/>Okundu ─░┼şaretle</Button>
                        <Button size="sm" onClick={() => handleBulkUpdate({ is_read: false })} className="bg-purple-600 hover:bg-purple-700"><EyeOff className="w-4 h-4 mr-2"/>Okunmad─▒ ─░┼şaretle</Button>
                        <Button size="sm" onClick={() => setIsDeleteModalOpen(true)} className="bg-red-600 hover:bg-red-700"><Trash2 className="w-4 h-4 mr-2"/>Sil</Button>
                    </div>
                </div>
            )}
            
            <div className="bg-slate-800/40 rounded-lg border border-slate-700/50 overflow-x-auto">
                <table className="w-full min-w-[800px] text-left">
                    <thead className="bg-slate-700/50">
                        <tr>
                            <th className="p-4 w-12"><Checkbox checked={isAllSelected} onCheckedChange={handleSelectAll} id="select-all"/></th>
                            <th className="px-3 py-4 text-sm font-semibold text-slate-300">Durum</th>
                            <th className="px-3 py-4 text-sm font-semibold text-slate-300 w-1/2">Mesaj</th>
                            <th className="px-3 py-4 text-sm font-semibold text-slate-300">┼Şube</th>
                            <th className="px-3 py-4 text-sm font-semibold text-slate-300">Tarih</th>
                        </tr>
                    </thead>
                    <tbody>
                        {loading ? (
                            [...Array(10)].map((_, i) => <tr key={i}><td colSpan="5" className="p-2"><div className="h-12 bg-slate-700/50 rounded-lg animate-pulse"></div></td></tr>)
                        ) : error ? (
                             <tr><td colSpan="5" className="text-center py-16"><ServerCrash className="w-12 h-12 text-red-500/50 mx-auto mb-4" /><p className="text-slate-400">{error}</p></td></tr>
                        ) : notifications.length === 0 ? (
                            <tr><td colSpan="5" className="text-center py-16"><Inbox className="w-12 h-12 text-slate-600 mx-auto mb-4" /><p className="text-slate-400">G├Âr├╝nt├╝lenecek bildirim yok.</p></td></tr>
                        ) : (
                            notifications.map(n => (
                                <tr 
                                    key={n.id} 
                                    className={`border-b border-slate-700/30 transition-colors cursor-pointer ${selected.includes(n.id) ? 'bg-blue-900/20' : 'hover:bg-slate-700/40'}`}
                                    onClick={() => handleNotificationClick(n)}
                                >
                                    <td className="p-4" onClick={(e) => e.stopPropagation()}>
                                        <Checkbox checked={selected.includes(n.id)} onCheckedChange={(checked) => setSelected(prev => checked ? [...prev, n.id] : prev.filter(id => id !== n.id))} />
                                    </td>
                                    <td className="px-3 py-4">
                                        <span className={`inline-block w-3 h-3 rounded-full ${n.is_read ? 'bg-slate-500' : 'bg-blue-400 animate-pulse'}`} title={n.is_read ? 'Okundu' : 'Okunmad─▒'}></span>
                                    </td>
                                    <td className="px-3 py-4">
                                        <div className="flex items-center gap-3">
                                            <MessageSquare className={`w-5 h-5 shrink-0 ${n.is_read ? 'text-slate-500' : 'text-teal-400'}`} />
                                            <div>
                                                <p className={`font-medium ${n.is_read ? 'text-slate-400' : 'text-white'}`}>{getNotificationLabel(n)}</p>
                                                <p className="text-xs text-slate-500">M├╝┼şteri: {n.customer_name || 'Bilinmiyor'}</p>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-3 py-4 text-sm text-slate-300">{n.branch_name || 'Genel'}</td>
                                    <td className="px-3 py-4 text-sm text-slate-400">{formatTimeAgo(n.created_at)}</td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {totalCount > 0 && (
                <div className="bg-slate-800/40 rounded-lg p-4 border border-slate-700/50 mt-4 flex flex-col md:flex-row items-center justify-between gap-4">
                    <p className="text-slate-400 text-sm">Toplam {totalCount} bildirim</p>
                    <div className="flex items-center gap-2">
                        <Button onClick={() => setPage(p => p - 1)} disabled={page === 1} size="sm" variant="outline" className="border-slate-700"><ChevronLeft className="w-4 h-4 mr-1"/>├ûnceki</Button>
                        <span className="text-sm text-white font-medium px-2">Sayfa {page} / {totalPages}</span>
                        <Button onClick={() => setPage(p => p + 1)} disabled={page >= totalPages} size="sm" variant="outline" className="border-slate-700">Sonraki<ChevronRight className="w-4 h-4 ml-1"/></Button>
                    </div>
                </div>
            )}
             <Dialog open={isDeleteModalOpen} onOpenChange={setIsDeleteModalOpen}><DialogContent className="bg-slate-900 border-slate-800 text-white"><DialogHeader><DialogTitle>Silme Onay─▒</DialogTitle><DialogDescription>Se├ğili {selected.length} bildirimi kal─▒c─▒ olarak silmek istedi─şinizden emin misiniz?</DialogDescription></DialogHeader><DialogFooter className="mt-4"><Button variant="outline" onClick={() => setIsDeleteModalOpen(false)}>─░ptal</Button><Button variant="destructive" onClick={handleBulkDelete}>Sil</Button></DialogFooter></DialogContent></Dialog>
        
             {/* Detail Modal */}
             {selectedFeedback && (
                 <FeedbackDetailModal 
                     isOpen={!!selectedFeedback}
                     onClose={() => setSelectedFeedback(null)}
                     feedback={selectedFeedback}
                     // Optional: If you want status updates here to reflect somewhere, handle it
                 />
             )}
        </div>
    );
};

export default NotificationHistory;

import React, { useEffect, useState, useRef } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { supabase } from '@/lib/customSupabaseClient';
import { Loader2, AlertCircle, ChevronDown, ChevronUp } from 'lucide-react';
import { useToast } from '@/components/ui/use-toast';
import { Button } from '@/components/ui/button';

const QRRedirector = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { toast } = useToast();

  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [debugInfo, setDebugInfo] = useState('');
  const [showDebug, setShowDebug] = useState(false);

  const processingRef = useRef(false);

  // ­şşó YEN─░: iOS'ta g├╝venli localStorage yazma
  const writeToStorageAsync = async (key, value) => {
    return new Promise((resolve) => {
      try {
        localStorage.setItem(key, value);
        // iOS'ta yazman─▒n tamamland─▒─ş─▒ndan emin ol
        const written = localStorage.getItem(key);
        if (written === value) {
          resolve(true);
        } else {
          console.warn(`Storage verification failed for ${key}`);
          resolve(false);
        }
      } catch (e) {
        console.warn(`Storage write error for ${key}:`, e);
        resolve(false);
      }
    });
  };

  useEffect(() => {
    if (processingRef.current) return;
    processingRef.current = true;

    const processQRScan = async () => {
      try {
        const qrCode = searchParams.get('qr') || searchParams.get('code');

        if (!qrCode) {
          throw new Error("URL'de QR kodu parametresi bulunamad─▒.");
        }

        // 1. ┼Şube Bilgisini ├çek
        const { data: branchData, error: branchError } = await supabase
          .from('branches')
          .select('id, business_id, branch_name_tr, qr_code')
          .eq('qr_code', qrCode)
          .single();

        if (branchError) throw { step: 'Branch Fetch', ...branchError };
        if (!branchData) throw { step: 'Branch Data', message: '┼Şube bulunamad─▒' };

        const { id: branch_id, business_id, branch_name_tr } = branchData;

        // 2. Taramay─▒ Supabase'e Logla (Kritik)
        const logResult = await supabase.from('qr_scans').insert({
          branch_id,
          business_id,
          qr_code: qrCode,
          user_agent: navigator.userAgent,
          created_at: new Date().toISOString()
        });

        if (logResult.error) {
          console.error("QR Insert Error:", logResult.error);
        }

        // 3. ­şşó YEN─░: localStorage'a yaz (PARALEL - ana ak─▒┼ş bloke edilmez)
        Promise.allSettled([
          writeToStorageAsync('vocalize_last_business', business_id),
          writeToStorageAsync('vocalize_last_branch', branch_id),
          (async () => {
            try {
              const existing = JSON.parse(localStorage.getItem('vocalize_visited_businesses') || '[]');
              if (!existing.includes(business_id)) {
                existing.push(business_id);
                await writeToStorageAsync('vocalize_visited_businesses', JSON.stringify(existing));
              }
              return true;
            } catch (e) {
              console.warn('Error updating visited businesses:', e);
              return false;
            }
          })()
        ]).catch(e => console.warn('Storage operations error:', e));

        // 4. Kullan─▒c─▒ Oturumunu Kontrol Et
        const { data: { session } } = await supabase.auth.getSession();

        if (session) {
          const userType = session.user?.user_metadata?.user_type;

          if (userType === 'manager') {
            await supabase.auth.signOut({ scope: 'local' });

            toast({
              title: "Oturum Sonland─▒r─▒ld─▒",
              description: "M├╝┼şteri paneline y├Ânlendirilmek ├╝zere Y├Ânetici hesab─▒n─▒zdan ├ğ─▒k─▒┼ş yap─▒lm─▒┼şt─▒r.",
              duration: 4000
            });

            setTimeout(() => {
              navigate(`/?business=${business_id}&branch=${branch_id}&qr=${qrCode}&openAuth=true&authTab=login`, { replace: true });
            }, 800);
            return;
          }

          // M├╝┼şteri ise
          const user_id = session.user.id;
          await supabase.from('customer_qr_scans').upsert({
            user_id,
            business_id,
            branch_id,
            qr_code: qrCode,
            last_scan_at: new Date().toISOString()
          }, {
            onConflict: 'user_id, business_id, branch_id, qr_code'
          });

          navigate(`/customer-panel?business=${business_id}&branch=${branch_id}&from_qr=true`, { replace: true });

        } else {
          // Misafir ise
          navigate(`/?business=${business_id}&branch=${branch_id}&qr=${qrCode}&openAuth=true&authTab=login`, { replace: true });
        }

      } catch (err) {
        console.error('QR Process Error:', err);
        const errorMsg = err.message || JSON.stringify(err, null, 2);
        setError('Ba─şlant─▒ s─▒ras─▒nda bir sorun olu┼ştu.');
        setDebugInfo(errorMsg);
        setIsLoading(false);
      }
    };

    processQRScan();
  }, [searchParams, navigate, toast]);

  if (isLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-[#0f172a] p-4">
        <div className="flex flex-col items-center animate-in fade-in duration-500">
          <Loader2 className="h-12 w-12 md:h-16 md:w-16 text-teal-500 animate-spin mb-6" />
          <p className="text-slate-400 text-base md:text-lg font-medium text-center">Y├Ânlendiriliyorsunuz...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-[#0f172a] p-4 overflow-auto">
        <div className="bg-slate-800 p-6 md:p-8 rounded-xl shadow-2xl max-w-md w-full text-center border-2 border-red-500/50">
          <div className="bg-slate-900/50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 border border-slate-700">
            <AlertCircle className="h-8 w-8 text-red-500" />
          </div>
          <h2 className="text-xl font-bold text-red-500 mb-2">Hata Olu┼ştu</h2>
          <p className="text-slate-400 mb-6 text-sm">{error}</p>

          <div className="mb-4">
            <button
              onClick={() => setShowDebug(!showDebug)}
              className="flex items-center justify-center gap-1 text-xs text-slate-500 hover:text-slate-300 w-full transition-colors"
            >
              {showDebug ? 'Teknik Detaylar─▒ Gizle' : 'Teknik Detaylar─▒ G├Âster'}
              {showDebug ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
            </button>

            {showDebug && (
              <div className="bg-black/50 p-3 rounded-lg text-left mt-2 overflow-auto max-h-48 animate-in slide-in-from-top-2">
                <p className="text-[10px] text-red-300 font-mono whitespace-pre-wrap break-all">
                  {debugInfo}
                </p>
              </div>
            )}
          </div>

          <Button onClick={() => window.location.reload()} className="w-full bg-teal-600 hover:bg-teal-700 text-white mb-3">Tekrar Dene</Button>
          <Button onClick={() => navigate('/')} variant="outline" className="w-full border-slate-600 text-slate-300 hover:bg-slate-700">Ana Sayfa</Button>
        </div>
      </div>
    );
  }

  return null;
};

export default QRRedirector;

import React, { useState, useEffect } from 'react';
import { supabase } from '@/lib/customSupabaseClient';
import { useAuth } from '@/contexts/SupabaseAuthContext';
import { useAdminContext } from '@/contexts/AdminContext';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useToast } from "@/components/ui/use-toast";
import { User, Lock, Save, MessageSquare, Loader2, Image as ImageIcon, Upload, X, Moon, Sun } from 'lucide-react';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";

const SettingsPage = () => {
  const { user } = useAuth();
  const { businessName } = useAdminContext();
  const { toast } = useToast();

  const [passwords, setPasswords] = useState({ new: '', confirm: '' });
  const [passwordLoading, setPasswordLoading] = useState(false);

  // Feedback Modal State
  const [feedbackModalOpen, setFeedbackModalOpen] = useState(false);
  const [feedbackMessage, setFeedbackMessage] = useState('');
  const [feedbackLoading, setFeedbackLoading] = useState(false);
  const [feedbackImages, setFeedbackImages] = useState([]);

  // Theme Management
  const [theme, setTheme] = useState(localStorage.getItem('acta_theme') || 'dark');

  useEffect(() => {
    const root = window.document.body;
    root.classList.remove('light-theme', 'dark-theme');

    if (theme === 'light') {
      root.classList.add('light-theme');
    } else {
      root.classList.add('dark-theme');
    }
    localStorage.setItem('acta_theme', theme);

    // Dispatch a custom event to sync with other components (like Header)
    window.dispatchEvent(new Event('theme-change'));
  }, [theme]);

  const toggleTheme = (newTheme) => {
    setTheme(newTheme);
  };

  // ­şşó MOB─░L GER─░ TU┼ŞU: Feedback Modal
  useEffect(() => {
    if (!feedbackModalOpen) return;

    const handlePopState = () => {

      setFeedbackModalOpen(false);
      setFeedbackMessage('');
      setFeedbackImages([]);
    };

    window.history.pushState({ feedbackModal: true }, '');
    window.addEventListener('popstate', handlePopState);

    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, [feedbackModalOpen]);

  // ­şşó MEMORY LEAK FIX: Image Preview URL Cleanup
  useEffect(() => {
    return () => {
      feedbackImages.forEach(file => {
        try {
          const url = URL.createObjectURL(file);
          URL.revokeObjectURL(url);
        } catch (e) {
          // Ignore errors
        }
      });
    };
  }, [feedbackImages]);

  const handlePasswordUpdate = async (e) => {
    e.preventDefault();
    if (passwords.new !== passwords.confirm) {
      toast({ variant: "destructive", title: "Hata", description: "┼Şifreler e┼şle┼şmiyor." });
      return;
    }
    if (passwords.new.length < 6) {
      toast({ variant: "destructive", title: "Hata", description: "┼Şifre en az 6 karakter olmal─▒." });
      return;
    }

    setPasswordLoading(true);
    const { error } = await supabase.auth.updateUser({ password: passwords.new });
    setPasswordLoading(false);

    if (error) {
      toast({ variant: "destructive", title: "Hata", description: error.message });
    } else {
      toast({ title: "Ba┼şar─▒l─▒", description: "┼Şifreniz g├╝ncellendi." });
      setPasswords({ new: '', confirm: '' });
    }
  };

  const handleImageChange = (e) => {
    const files = Array.from(e.target.files);
    const remainingSlots = 3 - feedbackImages.length;

    if (files.length > remainingSlots) {
      toast({
        title: "Uyar─▒",
        description: "En fazla 3 g├Ârsel ekleyebilirsiniz.",
        variant: "destructive"
      });
      return;
    }

    setFeedbackImages(prev => [...prev, ...files.slice(0, remainingSlots)]);
  };

  const removeImage = (index) => {
    setFeedbackImages(prev => prev.filter((_, i) => i !== index));
  };

  const uploadImages = async () => {
    const uploadedUrls = [];

    for (const file of feedbackImages) {
      const fileName = `manager-feedback/${Date.now()}_${Math.random().toString(36).substr(2, 9)}_${file.name.replace(/[^a-zA-Z0-9]/g, '')}`;

      const { data, error } = await supabase.storage
        .from('feedback-images')
        .upload(fileName, file);

      if (error) {
        console.error('Error uploading file:', error);
        continue;
      }

      const { data: { publicUrl } } = supabase.storage
        .from('feedback-images')
        .getPublicUrl(fileName);

      uploadedUrls.push(publicUrl);
    }

    return uploadedUrls;
  };

  const handleFeedbackSubmit = async (e) => {
    e.preventDefault();
    if (!user) {
      toast({ variant: "destructive", title: "Hata", description: "Oturum a├ğman─▒z gerekiyor." });
      return;
    }
    if (!feedbackMessage.trim()) {
      toast({ variant: "destructive", title: "Hata", description: "L├╝tfen mesaj─▒n─▒z─▒ yaz─▒n." });
      return;
    }

    setFeedbackLoading(true);
    try {
      let imageUrls = [];
      if (feedbackImages.length > 0) {
        imageUrls = await uploadImages();
      }

      const { error } = await supabase.from('vocalize_manager_feedbacks').insert({
        manager_id: user.id,
        message: feedbackMessage,
        images: imageUrls
      });

      if (error) throw error;

      toast({
        title: "Geri Bildirim Al─▒nd─▒",
        description: "Geri bildiriminiz i├ğin te┼şekk├╝r ederiz.",
        className: "bg-teal-600 text-white border-none"
      });
      setFeedbackMessage('');
      setFeedbackImages([]);
      setFeedbackModalOpen(false);
    } catch (error) {
      console.error('Feedback submit error:', error);
      toast({ variant: "destructive", title: "Hata", description: "Geri bildirim g├Ânderilemedi." });
    } finally {
      setFeedbackLoading(false);
    }
  };

  // ­şşó MODAL KAPATMA (History deste─şi ile)
  const handleCloseModal = () => {
    setFeedbackModalOpen(false);
    setFeedbackMessage('');
    setFeedbackImages([]);

    if (window.history.state?.feedbackModal) {
      window.history.back();
    }
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6 pt-16 md:pt-0 pb-10">
      <div className="flex justify-center md:justify-start">
        <h1 className="text-2xl font-bold text-white">Ayarlar</h1>
      </div>

      {/* Profile Section */}
      <div className="bg-slate-900 border border-slate-800 rounded-xl p-6">
        <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-800">
          <User className="w-5 h-5 text-blue-400" />
          <h2 className="text-lg font-semibold text-white">Profil Bilgileri</h2>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-sm text-slate-400">E-posta Adresi</label>
            <Input value={user?.email || ''} disabled className="bg-slate-950 border-slate-800 text-slate-500" />
          </div>
          <div className="space-y-2">
            <label className="text-sm text-slate-400">─░┼şletme Ad─▒</label>
            <Input value={businessName} disabled className="bg-slate-950 border-slate-800 text-slate-500" />
          </div>
        </div>
      </div>

      {/* Appearance Section */}
      <div className="bg-slate-900 border border-slate-800 rounded-xl p-6">
        <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-800">
          {theme === 'dark' ? <Moon className="w-5 h-5 text-indigo-400" /> : <Sun className="w-5 h-5 text-yellow-400" />}
          <h2 className="text-lg font-semibold text-white">G├Âr├╝n├╝m Ayarlar─▒</h2>
        </div>
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <label className="text-sm font-medium text-slate-200">Tema Tercihi</label>
            <p className="text-xs text-slate-400">Panelin g├Âr├╝n├╝m├╝n├╝ ayd─▒nl─▒k veya koyu mod olarak ayarlay─▒n.</p>
          </div>
          <div className="flex items-center bg-slate-950 p-1 rounded-lg border border-slate-800">
            <button
              onClick={() => toggleTheme('light')}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${theme === 'light' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <Sun className="w-4 h-4" />
              Ayd─▒nl─▒k
            </button>
            <button
              onClick={() => toggleTheme('dark')}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${theme === 'dark' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <Moon className="w-4 h-4" />
              Koyu
            </button>
          </div>
        </div>
      </div>

      {/* Password Section */}
      <div className="bg-slate-900 border border-slate-800 rounded-xl p-6">
        <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-800">
          <Lock className="w-5 h-5 text-orange-400" />
          <h2 className="text-lg font-semibold text-white">┼Şifre De─şi┼ştir</h2>
        </div>
        <form onSubmit={handlePasswordUpdate} className="space-y-4 max-w-md">
          <div className="space-y-2">
            <label className="text-sm text-slate-400">Yeni ┼Şifre</label>
            <Input
              type="password"
              value={passwords.new}
              onChange={(e) => setPasswords({ ...passwords, new: e.target.value })}
              className="bg-slate-800 border-slate-700 text-white"
              placeholder="ÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇó"
            />
          </div>
          <div className="space-y-2">
            <label className="text-sm text-slate-400">Yeni ┼Şifre (Tekrar)</label>
            <Input
              type="password"
              value={passwords.confirm}
              onChange={(e) => setPasswords({ ...passwords, confirm: e.target.value })}
              className="bg-slate-800 border-slate-700 text-white"
              placeholder="ÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇó"
            />
          </div>
          <Button disabled={passwordLoading} type="submit" className="w-full bg-teal-600 hover:bg-teal-700 text-white">
            {passwordLoading ? "G├╝ncelleniyor..." : <><Save className="w-4 h-4 mr-2" /> ┼Şifreyi G├╝ncelle</>}
          </Button>
        </form>
      </div>

      {/* Vocalize Feedback Section */}
      <div className="bg-slate-900 border border-slate-800 rounded-xl p-6">
        <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-800">
          <MessageSquare className="w-5 h-5 text-purple-400" />
          <h2 className="text-lg font-semibold text-white">Vocalize Ekibine Geri Bildirim G├Ânderin</h2>
        </div>
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
          <p className="text-slate-400 text-sm max-w-lg">
            Vocalize deneyiminizi iyile┼ştirmek i├ğin ├Âneri, ┼şikayet veya taleplerinizi do─şrudan bize iletebilirsiniz. Geri bildirimleriniz bizim i├ğin de─şerlidir.
          </p>
          <Button onClick={() => setFeedbackModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white whitespace-nowrap">
            <MessageSquare className="w-4 h-4 mr-2" />
            Geri Bildirim G├Ânder
          </Button>
        </div>
      </div>

      {/* ­şşó G├£NCELLENMI┼Ş MODAL (onOpenChange kullan─▒m─▒) */}
      <Dialog open={feedbackModalOpen} onOpenChange={handleCloseModal}>
        <DialogContent className="sm:max-w-[500px] bg-slate-900 border-slate-800 text-white">
          <DialogHeader>
            <DialogTitle className="text-white">Vocalize Ekibiyle ─░leti┼şim</DialogTitle>
            <DialogDescription className="text-slate-400">
              G├Âr├╝┼şlerinizi, ├Ânerilerinizi veya ya┼şad─▒─ş─▒n─▒z sorunlar─▒ bizimle payla┼ş─▒n.
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleFeedbackSubmit} className="grid gap-4 py-4">
            <div className="grid gap-2">
              <label htmlFor="feedback-message" className="text-sm font-medium text-slate-200">Mesaj─▒n─▒z *</label>
              <textarea
                id="feedback-message"
                rows="4"
                placeholder="Fikirlerinizi buraya yaz─▒n..."
                value={feedbackMessage}
                onChange={(e) => setFeedbackMessage(e.target.value)}
                className="w-full rounded-md border border-slate-700 bg-slate-800 px-3 py-2 text-sm text-white placeholder:text-slate-400 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 resize-none"
                required
              />
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <label className="text-sm font-medium text-slate-200 flex items-center gap-2">
                  <ImageIcon className="w-4 h-4" />
                  G├Ârseller (Opsiyonel)
                </label>
                <span className="text-xs text-slate-500">{feedbackImages.length}/3</span>
              </div>

              <div className="flex flex-wrap gap-3">
                {feedbackImages.map((file, idx) => (
                  <div key={idx} className="relative w-20 h-20 rounded-lg overflow-hidden border border-slate-700 group">
                    <img
                      src={URL.createObjectURL(file)}
                      alt="preview"
                      className="w-full h-full object-cover"
                    />
                    <button
                      type="button"
                      onClick={() => removeImage(idx)}
                      className="absolute top-1 right-1 bg-black/60 hover:bg-red-600 text-white rounded-full p-1 transition-colors"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  </div>
                ))}

                {feedbackImages.length < 3 && (
                  <label className="w-20 h-20 flex flex-col items-center justify-center border border-dashed border-slate-700 rounded-lg cursor-pointer hover:bg-slate-800/50 hover:border-blue-500/50 transition-colors">
                    <Upload className="w-5 h-5 text-slate-400 mb-1" />
                    <span className="text-[10px] text-slate-500">Y├╝kle</span>
                    <input
                      type="file"
                      accept="image/*"
                      multiple
                      className="hidden"
                      onChange={handleImageChange}
                    />
                  </label>
                )}
              </div>
            </div>

            <DialogFooter className="mt-2">
              <Button type="submit" disabled={feedbackLoading} className="bg-blue-600 hover:bg-blue-700 text-white w-full">
                {feedbackLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                G├Ânder
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default SettingsPage;

